// Class 12 Chemistry Unit VIII: Aldehydes, Ketones and Carboxylic Acids (Official Syllabus - 08 Marks)
// Comprehensive Deep Reference Book Standard (O.P. Tandon / Pradeep's Standard)

export const c12Chem8HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY CARD -->\n  <div style=\"background: rgba(255, 214, 0, 0.05); border: 1.5px solid #FFD600; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FFD600; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary &amp; Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FFD600; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Concepts &amp; Key Definitions &bull; Unit VIII: Aldehydes, Ketones and Carboxylic Acids (Official Syllabus - 08 Marks)</p>\n\n    <div style=\"display: flex; flex-direction: column; gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">1. Carbonyl Group (&gt;C=O):</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">A functional group consisting of a carbon atom double-bonded to an oxygen atom. In <b>Aldehydes (R-CHO)</b>, the carbonyl carbon is bonded to at least one hydrogen atom. In <b>Ketones (R-CO-R&apos;)</b>, it is bonded to two alkyl or aryl carbon atoms. In <b>Carboxylic Acids (R-COOH)</b>, the carbonyl carbon is bonded directly to a hydroxyl (-OH) group.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">2. Nucleophilic Addition to Carbonyl Group:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">Because oxygen is more electronegative than carbon, the carbonyl &pi;-bond is polarized (&gt;C<sup>&delta;+</sup>=O<sup>&delta;-</sup>). Nucleophiles attack the electrophilic sp<sup>2</sup> hybridised carbonyl carbon perpendicularly to form a tetrahedral alkoxide intermediate (sp<sup>3</sup>), followed by protonation. Reactivity order: <b>HCHO &gt; RCHO &gt; R-CO-R&apos; &gt; Aromatic aldehydes/ketones</b>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">3. Aldol Condensation:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">Carbonyl compounds possessing at least one <b>&alpha;-hydrogen</b> undergo self-addition in the presence of dilute base (e.g. dil. NaOH, Ba(OH)<sub>2</sub>) to form &beta;-hydroxyaldehydes (Aldols) or &beta;-hydroxyketones (Ketols), which upon heating eliminate water to yield <b>&alpha;,&beta;-unsaturated carbonyl compounds</b>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">4. Cannizzaro Reaction:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">Aldehydes having <b>NO &alpha;-hydrogen</b> (e.g. HCHO, C<sub>6</sub>H<sub>5</sub>CHO, (CH<sub>3</sub>)<sub>3</sub>C-CHO) undergo disproportionation (self-oxidation and reduction) upon heating with concentrated (50%) alkali (NaOH/KOH) to produce an equimolar mixture of a primary alcohol and a carboxylate salt.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">5. Tollens&apos; &amp; Fehling&apos;s Tests:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Tollens&apos; Reagent</b> [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> is reduced by aldehydes (both aliphatic &amp; aromatic) to form a shiny metallic <b>Silver Mirror</b>. <b>Fehling&apos;s Solution</b> (alkaline Cu<sup>2+</sup> tartrate) is reduced by <b>aliphatic aldehydes only</b> to a red-brown precipitate of <b>Cu<sub>2</sub>O</b> (Ketones and Benzaldehyde give negative Fehling&apos;s test).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">6. Iodoform (Haloform) Reaction:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">Compounds containing a methyl carbonyl group (<b>CH<sub>3</sub>-C=O</b>) or methyl carbinol group (<b>CH<sub>3</sub>-CH(OH)-</b>) react with sodium hypoiodite (I<sub>2</sub> + aq. NaOH) to give a characteristic <b>yellow crystalline precipitate of Iodoform (CHI<sub>3</sub>)</b> and a carboxylate salt containing one less carbon atom.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #FFD600; border-radius: 6px;\">\n        <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">7. Carboxylate Ion Resonance &amp; Hell-Volhard-Zelinsky (HVZ) Reaction:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Carboxylate ion (RCOO<sup>-</sup>)</b> is exceptionally stabilized by two equivalent resonance structures sharing negative charge equally over two electronegative oxygens. In the <b>HVZ reaction</b>, carboxylic acids with &alpha;-hydrogens react with Cl<sub>2</sub> or Br<sub>2</sub> in the presence of red phosphorus to yield <b>&alpha;-halocarboxylic acids</b>.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 30px;\">1. Nomenclature &amp; Classification of Aldehydes, Ketones and Carboxylic Acids</h2>\n\n  <p>Organic compounds containing carbon, hydrogen, and oxygen form the foundation of vital synthetic and biological processes. Aldehydes, ketones, and carboxylic acids all feature carbonyl groups with distinct electronic and steric environments that govern their physical properties and chemical reactivity.</p>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Classification of Oxygenated Organic Compounds\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Systematic Classification of Oxygenated Organic Compounds:</b> Core functional division of C, H, O families into Alcohols (R-OH), Aldehydes (R-CHO), Ketones (R-CO-R'), and Carboxylic Acids (R-COOH), subdivided into aliphatic and aromatic subclasses.\n  </div>\n</div>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. IUPAC Rules for Aldehydes (-al) &amp; Ketones (-one)</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Aldehydes:</b> Suffix is <b>-al</b> (e.g. HCHO: Methanal; CH<sub>3</sub>CHO: Ethanal; CH<sub>3</sub>CH<sub>2</sub>CHO: Propanal). The -CHO carbon is always numbered as C-1. When -CHO is attached directly to a ring, the suffix <b>-carbaldehyde</b> is used (e.g. Cyclohexanecarbaldehyde; Benzenecarbaldehyde / Benzaldehyde).<br>\n        <b style=\"color: #FFD600;\">&bull; Ketones:</b> Suffix is <b>-one</b> (e.g. CH<sub>3</sub>COCH<sub>3</sub>: Propan-2-one / Acetone; CH<sub>3</sub>COCH<sub>2</sub>CH<sub>3</sub>: Butan-2-one). Numbering starts from the end nearer to the carbonyl carbon.<br>\n        <b style=\"color: #FFD600;\">&bull; Symmetrical vs Asymmetrical Ketones:</b> Symmetrical (e.g. Propanone, Pentan-3-one) vs Mixed (e.g. Butan-2-one, Acetophenone C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub>).\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">2. IUPAC Rules for Carboxylic Acids (-oic acid) &amp; Dicarboxylic Acids</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Monocarboxylic Acids:</b> Suffix is <b>-oic acid</b> (e.g. HCOOH: Methanoic acid / Formic acid; CH<sub>3</sub>COOH: Ethanoic acid / Acetic acid; C<sub>6</sub>H<sub>5</sub>COOH: Benzoic acid).<br>\n        <b style=\"color: #FFD600;\">&bull; Dicarboxylic Acids:</b> Named as alkanedioic acids (e.g. HOOC-COOH: Ethanedioic acid / Oxalic acid; HOOC-CH<sub>2</sub>-COOH: Propanedioic acid / Malonic acid; HOOC-(CH<sub>2</sub>)<sub>2</sub>-COOH: Butanedioic acid / Succinic acid; HOOC-(CH<sub>2</sub>)<sub>4</sub>-COOH: Hexanedioic acid / Adipic acid).\n      </div>\n    </div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Aldehydes Structure and Properties\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Aldehydes Structure &amp; Chemical Behavior:</b> Ethanal (CH<sub>3</sub>CHO) containing the terminal formyl group (-CHO). Features high oxidation susceptibility, positive Tollens' and Fehling's tests, volatility, and extensive use in perfumes and flavourings.\n  </div>\n</div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Ketones Structure and Properties\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Ketones Structure &amp; Properties:</b> Propanone (CH<sub>3</sub>COCH<sub>3</sub> / Acetone) with a non-terminal carbonyl carbon. Demonstrates moderate nucleophilic reactivity, resistance to mild oxidants (negative Tollens'/Fehling's tests), and heavy industrial solvent utility.\n  </div>\n</div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Carboxylic Acids Structure and Acidity\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Carboxylic Acids Structure &amp; Acidity:</b> Ethanoic acid (CH<sub>3</sub>COOH) containing the carboxyl group (-COOH). Displays elevated boiling points due to cyclic dimer formation and distinct Bronsted acidity (turning blue litmus red and forming carboxylate salts).\n  </div>\n</div>\n\n  <div style=\"background: rgba(255, 214, 0, 0.08); border-left: 4.5px solid #FFD600; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD600; font-size: 16.5px; display: block; margin-bottom: 6px;\">📝 WORKED IUPAC NOMENCLATURE EXAMPLES</b>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.65; background: rgba(0,0,0,0.25); padding: 12px; border-radius: 6px;\">\n      <b style=\"color: #FFD600;\">1. CH<sub>3</sub>-CH(CH<sub>3</sub>)-CH<sub>2</sub>-CHO:</b> 3-Methylbutanal.<br>\n      <b style=\"color: #FFD600;\">2. CH<sub>3</sub>-CH=CH-CHO:</b> But-2-en-1-al (Crotonaldehyde).<br>\n      <b style=\"color: #FFD600;\">3. CH<sub>3</sub>-CO-CH<sub>2</sub>-CH(CH<sub>3</sub>)<sub>2</sub>:</b> 4-Methylpentan-2-one.<br>\n      <b style=\"color: #FFD600;\">4. C<sub>6</sub>H<sub>5</sub>-CO-CH<sub>3</sub>:</b> 1-Phenylethan-1-one (Acetophenone).<br>\n      <b style=\"color: #FFD600;\">5. C<sub>6</sub>H<sub>5</sub>-CO-C<sub>6</sub>H<sub>5</sub>:</b> Diphenylmethanone (Benzophenone).<br>\n      <b style=\"color: #FFD600;\">6. HOOC-CH<sub>2</sub>-CH(COOH)-CH<sub>2</sub>-COOH:</b> Propane-1,2,3-tricarboxylic acid (when &ge;3 -COOH groups are on chain, none is included in parent chain).<br>\n      <b style=\"color: #FFD600;\">7. o-HOC<sub>6</sub>H<sub>4</sub>COOH:</b> 2-Hydroxybenzoic acid (Salicylic acid).\n    </div>\n  </div>\n\n  <!-- SECTION 2 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">2. Structure &amp; Nature of the Carbonyl Group (&gt;C=O)</h2>\n\n  <div style=\"background: rgba(255, 214, 0, 0.08); border-left: 4.5px solid #FFD600; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD600; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 ELECTRONIC STRUCTURE &amp; POLARITY OF CARBONYL GROUP</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">\n      <b style=\"color: #FFD600;\">1. Hybridisation &amp; Geometry:</b> The carbonyl carbon atom is <b>sp<sup>2</sup> hybridised</b> and forms three &sigma;-bonds in a coplanar trigonal arrangement with bond angles of approximately <b>120&deg;</b>. The fourth valence electron of carbon remains in an unhybridised 2p orbital which undergoes lateral overlap with a parallel 2p orbital of the oxygen atom to form a <b>&pi;-bond</b>.<br><br>\n      <b style=\"color: #FFD600;\">2. Dipole Moment &amp; Polarity:</b> Oxygen is significantly more electronegative (3.5) than carbon (2.5). The &pi;-electron density is strongly shifted towards oxygen, resulting in large bond dipole moments (<b>&mu; = 2.3 &mdash; 2.8 D</b>):\n      <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 10px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">&gt;C=O &#8654; &gt;C<sup>+</sup>-O<sup>-</sup> &nbsp;&nbsp; (Electrophilic Carbon &bull; Nucleophilic Oxygen)</div>\n      <b style=\"color: #FFD600;\">3. Electrophilic vs Nucleophilic Sites:</b> The carbonyl carbon is an <b>electrophilic (Lewis acid) center</b> susceptible to attack by nucleophiles, whereas the carbonyl oxygen is a <b>nucleophilic (Lewis base) center</b> susceptible to protonation by electrophiles.\n    </div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"General Structure and Functional Groups of Oxygen Compounds\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Comparative Spatial Geometries of Oxygen Functional Groups:</b> 3D structural comparison of Hydroxyl (-OH, bent sp<sup>3</sup>), Formyl (-CHO, trigonal planar sp<sup>2</sup>), Carbonyl (&gt;C=O, planar sp<sup>2</sup>), and Carboxyl (-COOH, planar resonance hybrid).\n  </div>\n</div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Alcohols Structure and Core Reactions\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Alcohols Structure &amp; Synthetic Role:</b> Methanol (CH<sub>3</sub>OH) with tetrahedral sp<sup>3</sup> C-O geometry. Alcohols serve as direct precursors to aldehydes, ketones, and esters via oxidation and Fischer esterification.\n  </div>\n</div>\n\n  <!-- SECTION 3 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">3. Methods of Preparation of Aldehydes and Ketones</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. General Methods for Both Aldehydes &amp; Ketones</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Oxidation of Alcohols:</b> 1&deg; Alcohol &rarr; (PCC in CH<sub>2</sub>Cl<sub>2</sub>) &rarr; <b>Aldehyde</b>; 2&deg; Alcohol &rarr; (CrO<sub>3</sub> / H<sub>2</sub>SO<sub>4</sub>) &rarr; <b>Ketone</b>.<br>\n        <b style=\"color: #FFD600;\">&bull; Dehydrogenation of Alcohols over Heated Cu (573 K):</b> 1&deg; Alcohol &rarr; Aldehyde + H<sub>2</sub>&uarr;; 2&deg; Alcohol &rarr; Ketone + H<sub>2</sub>&uarr;.<br>\n        <b style=\"color: #FFD600;\">&bull; Ozonolysis of Alkenes:</b> Alkene + O<sub>3</sub> &rarr; Ozonide &rarr; (Zn / H<sub>2</sub>O) &rarr; Aldehydes / Ketones (Zn dust prevents oxidation to acids by destroying H<sub>2</sub>O<sub>2</sub>).<br>\n        <b style=\"color: #FFD600;\">&bull; Hydration of Alkynes (Kucherov Reaction):</b> Ethyne + H<sub>2</sub>O &rarr; (40% H<sub>2</sub>SO<sub>4</sub> + 1% HgSO<sub>4</sub> / 333 K) &rarr; [CH<sub>2</sub>=CHOH] &rarr; <b>Acetaldehyde (CH<sub>3</sub>CHO)</b>; Propyne &rarr; <b>Acetone (CH<sub>3</sub>COCH<sub>3</sub>)</b>.\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">2. Exclusive Named Methods for Preparation of Aldehydes</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Rosenmund Reduction:</b> Catalytic hydrogenation of acyl chloride over palladium poisoned with BaSO<sub>4</sub> (and sulfur/quinoline):<br>\n        <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 8px 0; font-size: 15px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">R-COCl + H<sub>2</sub> &rarr; (Pd - BaSO<sub>4</sub> / Boiling xylene) &rarr; R-CHO + HCl</div>\n        <i>(BaSO<sub>4</sub> acts as a catalyst poison to prevent further reduction of aldehyde to alcohol).</i><br><br>\n        <b style=\"color: #FFD600;\">&bull; Stephen Reaction:</b> Nitrile reduction by SnCl<sub>2</sub>/HCl followed by steam distillation:<br>\n        <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 8px 0; font-size: 15px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">R-C&equiv;N + SnCl<sub>2</sub> + HCl &rarr; R-CH=NH&bull;HCl (Aldimine) &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; R-CHO + NH<sub>4</sub>Cl</div>\n        <b style=\"color: #FFD600;\">&bull; DIBAL-H Reduction:</b> Diisobutylaluminium hydride reduces nitriles and esters selectively to aldehydes at 195 K.<br><br>\n        <b style=\"color: #FFD600;\">&bull; Etard Reaction (Aromatic Aldehyde):</b> Toluene is oxidized by Chromyl chloride (CrO<sub>2</sub>Cl<sub>2</sub>) in CS<sub>2</sub> to form a brown chromium complex, which on hydrolysis yields <b>Benzaldehyde</b>:<br>\n        <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 8px 0; font-size: 15px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">C<sub>6</sub>H<sub>5</sub>CH<sub>3</sub> + 2 CrO<sub>2</sub>Cl<sub>2</sub> &rarr; (CS<sub>2</sub>) &rarr; C<sub>6</sub>H<sub>5</sub>CH(OCrOHCl<sub>2</sub>)<sub>2</sub> &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; C<sub>6</sub>H<sub>5</sub>CHO</div>\n        <b style=\"color: #FFD600;\">&bull; Gattermann-Koch Reaction:</b> Benzene + CO + HCl &rarr; (anhyd. AlCl<sub>3</sub> / CuCl) &rarr; <b>Benzaldehyde</b>.\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">3. Exclusive Methods for Preparation of Ketones</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; From Acyl Chlorides with Dialkylcadmium:</b> 2 R&apos;-COCl + R<sub>2</sub>Cd &rarr; 2 R&apos;-CO-R + CdCl<sub>2</sub> (Cadmium alkyls are less reactive and do not react with the ketone product).<br>\n        <b style=\"color: #FFD600;\">&bull; From Nitriles with Grignard Reagents:</b> CH<sub>3</sub>-C&equiv;N + C<sub>6</sub>H<sub>5</sub>MgBr &rarr; (Ether) &rarr; CH<sub>3</sub>-C(=NMgBr)-C<sub>6</sub>H<sub>5</sub> &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; <b>Acetophenone (C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub>)</b>.<br>\n        <b style=\"color: #FFD600;\">&bull; Friedel-Crafts Acylation:</b> Benzene + CH<sub>3</sub>COCl / (CH<sub>3</sub>CO)<sub>2</sub>O &rarr; (anhyd. AlCl<sub>3</sub>) &rarr; <b>Acetophenone</b> + HCl.\n      </div>\n    </div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Key Reaction Interconversions and Esterification\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Key Reaction Interconversions:</b> Oxidation of 1&deg; alcohols to aldehydes (RCH<sub>2</sub>OH &rarr; RCHO), 2&deg; alcohols to ketones (R<sub>2</sub>CHOH &rarr; R<sub>2</sub>C=O), aldehyde oxidation to carboxylic acids (RCHO &rarr; RCOOH), and acid-catalysed Fischer esterification (RCOOH + R'OH &#8652; RCOOR' + H<sub>2</sub>O).\n  </div>\n</div>\n\n  <!-- SECTION 4 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">4. Physical Properties &amp; Mechanism of Nucleophilic Addition Reactions</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. Physical Properties &amp; Boiling Point Order</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Boiling Point Hierarchy:</b> Alkanes &lt; Ethers &lt; <b>Aldehydes &lt; Ketones</b> &lt; Alcohols &lt; Carboxylic Acids.<br>\n        <i>Aldehydes &amp; ketones have higher boiling points than alkanes due to dipole-dipole attractions, but lower than alcohols because they lack intermolecular H-bonding. Ketones have slightly higher boiling points than isomeric aldehydes due to greater polarity.</i><br>\n        <b style=\"color: #FFD600;\">&bull; Water Solubility:</b> Lower aldehydes/ketones (up to 4 carbons) are completely miscible in water by forming H-bonds with water molecules.\n      </div>\n    </div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Physical Properties Trends of Oxygenated Families\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Comparative Physical Property Trends:</b> Intermolecular hydrogen bonding dictates high boiling points in alcohols and carboxylic acid cyclic dimers, while dipole-dipole interactions govern intermediate volatility in aldehydes and ketones.\n  </div>\n</div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Comparative Table of Oxygenated Organic Families\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Master Property Comparison Matrix:</b> Comprehensive overview contrasting functional group, general formula, bond polarity, boiling point hierarchy (Carboxylic acids &gt; Alcohols &gt;&gt; Ketones &ge; Aldehydes), and relative acidic strengths.\n  </div>\n</div>\n\n  <!-- NUCLEOPHILIC ADDITION MECHANISM BOX -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.4);\">\n    <div style=\"color: #FFD600; font-weight: bold; font-size: 16.5px; margin-bottom: 12px; border-bottom: 1px solid rgba(255, 214, 0, 0.3); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP BOARD MECHANISM: Nucleophilic Addition to Carbonyl Group\n    </div>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.75;\">\n      <b style=\"color: #FFD600;\">Step 1: Nucleophilic Attack (Slow, Rate-Determining Step)</b><br>\n      A nucleophile (Nu<sup>-</sup>) attacks the electrophilic sp<sup>2</sup> hybridised carbonyl carbon perpendicularly (at &approx; 107&deg; angle), rehybridising the carbon from planar sp<sup>2</sup> to tetrahedral sp<sup>3</sup> and forming an alkoxide intermediate:<br>\n      <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 10px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">&gt;C=O (Planar sp<sup>2</sup>) + Nu<sup>-</sup> &rarr; (Slow, RDS) &rarr; &gt;C(Nu)-O<sup>-</sup> (Tetrahedral Intermediate sp<sup>3</sup>)</div>\n\n      <b style=\"color: #FFD600;\">Step 2: Proton Transfer (Fast Step)</b><br>\n      The tetrahedral alkoxide captures a proton (H<sup>+</sup>) from the medium to yield the electrically neutral addition product:<br>\n      <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 10px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">&gt;C(Nu)-O<sup>-</sup> + H<sup>+</sup> &rarr; (Fast) &rarr; &gt;C(Nu)-OH</div>\n\n      <b style=\"color: #FFD600;\">Relative Reactivity Order:</b> <b>HCHO &gt; CH<sub>3</sub>CHO &gt; CH<sub>3</sub>COCH<sub>3</sub> &gt; C<sub>6</sub>H<sub>5</sub>CHO &gt; C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub> &gt; C<sub>6</sub>H<sub>5</sub>COC<sub>6</sub>H<sub>5</sub></b>.<br>\n      <b style=\"color: #FFD600;\">&bull; Steric Reason:</b> Bulky alkyl groups crowd the transition state and hinder the approach of nucleophiles.<br>\n      <b style=\"color: #FFD600;\">&bull; Electronic Reason:</b> Alkyl groups (+I effect) disperse the positive charge on carbonyl carbon, reducing electrophilicity. Resonance (+R) in aromatic carbonyls delocalizes &pi;-electrons into the ring, reducing carbonyl carbon positivity.\n    </div>\n  </div>\n\n  <!-- SECTION 5 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">5. Addition-Elimination Reactions with Ammonia Derivatives (H<sub>2</sub>N-Z)</h2>\n\n  <div style=\"background: rgba(255, 214, 0, 0.08); border-left: 4.5px solid #FFD600; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD600; font-size: 16.5px; display: block; margin-bottom: 6px;\">MASTER REACTION MATRIX: Carbonyl + H<sub>2</sub>N-Z &rarr; &gt;C=N-Z + H<sub>2</sub>O (pH 3.5 &mdash; 4.5)</b>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75; background: rgba(0,0,0,0.25); padding: 12px; border-radius: 6px;\">\n      <b style=\"color: #FFD600;\">1. With Hydroxylamine (H<sub>2</sub>N-OH):</b> Forms <b>Oximes</b> (&gt;C=N-OH).<br>\n      <b style=\"color: #FFD600;\">2. With Hydrazine (H<sub>2</sub>N-NH<sub>2</sub>):</b> Forms <b>Hydrazones</b> (&gt;C=N-NH<sub>2</sub>).<br>\n      <b style=\"color: #FFD600;\">3. With Phenylhydrazine (H<sub>2</sub>N-NHC<sub>6</sub>H<sub>5</sub>):</b> Forms <b>Phenylhydrazones</b> (&gt;C=N-NHC<sub>6</sub>H<sub>5</sub>).<br>\n      <b style=\"color: #FFD600;\">4. With 2,4-DNP (Brady&apos;s Reagent):</b> Forms yellow/orange crystalline <b>2,4-Dinitrophenylhydrazones</b> (used for characterization of aldehydes and ketones).<br>\n      <b style=\"color: #FFD600;\">5. With Semicarbazide (H<sub>2</sub>N-NH-CONH<sub>2</sub>):</b> Forms <b>Semicarbazones</b> (&gt;C=N-NH-CONH<sub>2</sub>).<br>\n      <b style=\"color: #FFD600;\">CRUCIAL BOARD TRAP:</b> In semicarbazide, only the hydrazine -NH<sub>2</sub> group acts as a nucleophile. The amide -NH<sub>2</sub> is unreactive because its lone pair is delocalized in resonance with the amide C=O group (-NH-C(=O)-NH<sub>2</sub> &#8654; -NH-C(O<sup>-</sup>)=N<sup>+</sup>H<sub>2</sub>).\n    </div>\n  </div>\n\n  <!-- SECTION 6 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">6. Oxidation, Reduction &amp; Diagnostic Chemical Tests</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. Deoxygenation Reductions: Clemmensen vs Wolff-Kishner</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Clemmensen Reduction:</b> &gt;C=O + 4 [H] &rarr; (<b>Zn-Hg + conc. HCl</b> / Heat) &rarr; <b>&gt;CH<sub>2</sub> (Hydrocarbon)</b> + H<sub>2</sub>O. (Suitable for acid-stable substrates).<br>\n        <b style=\"color: #FFD600;\">&bull; Wolff-Kishner Reduction:</b> &gt;C=O + NH<sub>2</sub>NH<sub>2</sub> &rarr; &gt;C=N-NH<sub>2</sub> &rarr; (<b>KOH / Ethylene glycol / 453-473 K</b>) &rarr; <b>&gt;CH<sub>2</sub></b> + N<sub>2</sub>&uarr;. (Suitable for base-stable substrates).\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">2. Distinction Tests: Tollens&apos;, Fehling&apos;s &amp; Iodoform Tests</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Tollens&apos; Test (Ammoniacal AgNO<sub>3</sub>):</b> Aldehyde + 2 [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> + 3 OH<sup>-</sup> &rarr; R-COO<sup>-</sup> + <b>2 Ag&darr; (Bright Silver Mirror)</b> + 4 NH<sub>3</sub> + 2 H<sub>2</sub>O.<br>\n        <b style=\"color: #FFD600;\">&bull; Fehling&apos;s Test:</b> Aliphatic aldehyde + 2 Cu<sup>2+</sup> + 5 OH<sup>-</sup> &rarr; R-COO<sup>-</sup> + <b>Cu<sub>2</sub>O&darr; (Red-Brown Precipitate)</b> + 3 H<sub>2</sub>O. (Ketones &amp; Benzaldehyde do NOT reduce Fehling&apos;s solution).<br>\n        <b style=\"color: #FFD600;\">&bull; Iodoform Test:</b> CH<sub>3</sub>-CO-R + 3 I<sub>2</sub> + 4 NaOH &rarr; <b>CHI<sub>3</sub>&darr; (Yellow crystals, MP 119 &deg;C)</b> + R-COONa + 3 NaI + 3 H<sub>2</sub>O.\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 7 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">7. Reactivity of &alpha;-Hydrogen: Aldol Condensation &amp; Cannizzaro Reaction</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. Acidity of &alpha;-Hydrogen &amp; Aldol Condensation</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        The &alpha;-hydrogens of carbonyls are acidic (pK<sub>a</sub> &approx; 19-20) due to electron-withdrawing effect of C=O and resonance stabilization of the enolate anion.<br>\n        <b style=\"color: #FFD600;\">&bull; Aldol Condensation:</b> 2 CH<sub>3</sub>CHO &rarr; (dil. NaOH) &rarr; CH<sub>3</sub>-CH(OH)-CH<sub>2</sub>-CHO (3-Hydroxybutanal / Aldol) &rarr; (&Delta;, -H<sub>2</sub>O) &rarr; <b>CH<sub>3</sub>-CH=CH-CHO (But-2-enal / Crotonaldehyde)</b>.<br>\n        <b style=\"color: #FFD600;\">&bull; Cross Aldol:</b> Between two different carbonyls. If both have &alpha;-H, 4 products are formed. Between Benzaldehyde and Acetophenone: C<sub>6</sub>H<sub>5</sub>CHO + CH<sub>3</sub>COC<sub>6</sub>H<sub>5</sub> &rarr; (OH<sup>-</sup> / &Delta;) &rarr; <b>C<sub>6</sub>H<sub>5</sub>-CH=CH-CO-C<sub>6</sub>H<sub>5</sub> (Benzalacetophenone / Chalcone)</b>.\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">2. Cannizzaro Reaction (Aldehydes with NO &alpha;-Hydrogen)</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        When aldehydes lacking &alpha;-hydrogens are heated with 50% NaOH, hydride transfer causes self-redox:<br>\n        <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 8px 0; font-size: 15px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">2 HCHO + conc. NaOH &rarr; CH<sub>3</sub>OH (Methanol) + HCOONa (Sodium formate)</div>\n        <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 8px 0; font-size: 15px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">2 C<sub>6</sub>H<sub>5</sub>CHO + conc. KOH &rarr; C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>OH (Benzyl alcohol) + C<sub>6</sub>H<sub>5</sub>COOK (Potassium benzoate)</div>\n        <b style=\"color: #FFD600;\">&bull; Cross Cannizzaro:</b> HCHO + C<sub>6</sub>H<sub>5</sub>CHO + conc. NaOH &rarr; <b>HCOONa + C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>OH</b> (Formaldehyde is more electrophilic and oxidizes preferentially).\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 8 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">8. Carboxylic Acids: Methods of Preparation &amp; Physical Properties</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. Methods of Preparation</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Oxidation of Alkylbenzenes:</b> Heating alkylbenzene with alkaline KMnO₄ followed by acidification gives <b>Benzoic acid</b> regardless of side chain length (provided &alpha;-H is present; tert-butylbenzene is inert).<br>\n        <b style=\"color: #FFD600;\">&bull; Hydrolysis of Nitriles:</b> R-C&equiv;N + H<sub>2</sub>O &rarr; (H<sup>+</sup> or OH<sup>-</sup>) &rarr; R-CONH<sub>2</sub> &rarr; (H<sub>3</sub>O<sup>+</sup> / &Delta;) &rarr; <b>R-COOH + NH<sub>4</sub><sup>+</sup></b>.<br>\n        <b style=\"color: #FFD600;\">&bull; Grignard Reagent Carbonation:</b> R-MgX + CO<sub>2</sub> (Dry ice) &rarr; R-COOMgX &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; <b>R-COOH</b> (Increases chain length by 1 carbon).<br>\n        <b style=\"color: #FFD600;\">&bull; Hydrolysis of Esters, Anhydrides &amp; Acyl Halides:</b> R-COCl + H<sub>2</sub>O &rarr; R-COOH + HCl.\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">2. Physical Properties &amp; Cyclic Dimer Formation</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        Carboxylic acids have remarkably higher boiling points than alcohols of similar molecular weight because they form strong, stable <b>intermolecular Hydrogen-Bonded Cyclic Dimers</b> that persist even in the vapour phase.\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 9 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">9. Acidic Nature of Carboxylic Acids &amp; Substituent Effects</h2>\n\n  <div style=\"background: rgba(255, 214, 0, 0.08); border-left: 4.5px solid #FFD600; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD600; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 RESONANCE STABILITY &amp; SUBSTITUENT EFFECT HIERARCHY</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">\n      <b style=\"color: #FFD600;\">1. Carboxylate Ion Resonance:</b> The carboxylate anion (RCOO<sup>-</sup>) is stabilized by <b>two equivalent resonance structures</b> with negative charge delocalized over two highly electronegative oxygen atoms. In contrast, phenoxide ion delocalizes charge onto less electronegative carbons with non-equivalent structures.<br><br>\n      <b style=\"color: #FFD600;\">2. Electron-Withdrawing Groups (-I, -M):</b> Disperse negative charge, stabilize carboxylate ion, and <b>increase acidity</b> (lower pK<sub>a</sub>):<br>\n      <b>CF<sub>3</sub>COOH &gt; CCl<sub>3</sub>COOH &gt; CHCl<sub>2</sub>COOH &gt; NO<sub>2</sub>CH<sub>2</sub>COOH &gt; NC-CH<sub>2</sub>COOH &gt; FCH<sub>2</sub>COOH &gt; ClCH<sub>2</sub>COOH &gt; BrCH<sub>2</sub>COOH &gt; HCOOH &gt; C<sub>6</sub>H<sub>5</sub>COOH &gt; CH<sub>3</sub>COOH</b>.<br><br>\n      <b style=\"color: #FFD600;\">3. Ortho Effect in Benzoic Acids:</b> Nearly all ortho-substituted benzoic acids are stronger acids than benzoic acid regardless of whether the substituent is electron-withdrawing or electron-donating due to steric inhibition of resonance.\n    </div>\n  </div>\n\n  <!-- SECTION 10 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">10. Chemical Reactions of Carboxylic Acids: HVZ &amp; Decarboxylation</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">1. Hell-Volhard-Zelinsky (HVZ) Reaction</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        Carboxylic acids containing an <b>&alpha;-hydrogen</b> react with Cl<sub>2</sub> or Br<sub>2</sub> in the presence of a catalytic amount of <b>red phosphorus</b> followed by hydrolysis to yield <b>&alpha;-halocarboxylic acids</b>:<br>\n        <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 214, 0, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 8px 0; font-size: 15px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">R-CH<sub>2</sub>-COOH + X<sub>2</sub> / Red P &rarr; (H<sub>2</sub>O) &rarr; R-CH(X)-COOH (&alpha;-Halocarboxylic acid)</div>\n      </div>\n    </div>\n\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 214, 0, 0.35); border-left: 5px solid #FFD600; border-radius: 8px; padding: 14px 16px;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 6px;\">2. Decarboxylation &amp; Other Key Reactions</b>\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.65;\">\n        <b style=\"color: #FFD600;\">&bull; Soda-Lime Decarboxylation:</b> R-COONa + NaOH &rarr; (CaO / &Delta;) &rarr; <b>R-H (Alkane with 1 less carbon)</b> + Na<sub>2</sub>CO<sub>3</sub>.<br>\n        <b style=\"color: #FFD600;\">&bull; Reduction:</b> R-COOH &rarr; (1. LiAlH<sub>4</sub> or B<sub>2</sub>H<sub>6</sub>, 2. H<sub>3</sub>O<sup>+</sup>) &rarr; <b>R-CH<sub>2</sub>OH (1&deg; Alcohol)</b>. (NaBH<sub>4</sub> does NOT reduce -COOH).<br>\n        <b style=\"color: #FFD600;\">&bull; Formation of Acid Chlorides:</b> R-COOH + SOCl<sub>2</sub> &rarr; <b>R-COCl</b> + SO<sub>2</sub>&uarr; + HCl&uarr;.<br>\n        <b style=\"color: #FFD600;\">&bull; Reaction with NH<sub>3</sub>:</b> R-COOH + NH<sub>3</sub> &#8652; R-COONH<sub>4</sub> &rarr; (&Delta;) &rarr; <b>R-CONH<sub>2</sub> (Amide)</b> &rarr; (P<sub>2</sub>O<sub>5</sub> / &Delta;) &rarr; <b>R-CN</b>.\n      </div>\n    </div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n  <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n    <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Uses and Importance of Carbonyl Compounds and Acids\" />\n  </div>\n  <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n    💡 <b>Commercial Applications &amp; Industrial Significance:</b> Everyday and industrial uses spanning antiseptics/fuels (alcohols), flavours/formalin disinfectants (aldehydes), pharmaceutical solvents (ketones), and culinary vinegar/polymers/medicines (carboxylic acids).\n  </div>\n</div>\n\n  <!-- SECTION 11 -->\n  <h2 style=\"color: #FFD600; border-bottom: 2px solid #FFD600; padding-bottom: 6px; margin-top: 36px;\">11. Master Revision Formula &amp; Named Reactions Cheat Sheet</h2>\n\n  <div style=\"background: rgba(255, 214, 0, 0.05); border: 1.5px solid rgba(255, 214, 0, 0.4); border-radius: 12px; padding: 18px; margin: 20px 0;\">\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.85;\">\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">1. Key Reaction Matrix:</b>\n      <b style=\"color: #FFD600;\">&bull; Rosenmund:</b> RCOCl + H<sub>2</sub> &rarr; (Pd-BaSO<sub>4</sub>) &rarr; RCHO + HCl.<br>\n      <b style=\"color: #FFD600;\">&bull; Stephen:</b> RCN + SnCl<sub>2</sub>/HCl &rarr; RCH=NH &rarr; RCHO.<br>\n      <b style=\"color: #FFD600;\">&bull; Etard:</b> Toluene + CrO<sub>2</sub>Cl<sub>2</sub> &rarr; Benzaldehyde.<br>\n      <b style=\"color: #FFD600;\">&bull; Gattermann-Koch:</b> Benzene + CO + HCl &rarr; (AlCl<sub>3</sub>/CuCl) &rarr; Benzaldehyde.<br>\n      <b style=\"color: #FFD600;\">&bull; Clemmensen:</b> &gt;C=O + Zn-Hg/conc. HCl &rarr; &gt;CH<sub>2</sub>.<br>\n      <b style=\"color: #FFD600;\">&bull; Wolff-Kishner:</b> &gt;C=O + NH<sub>2</sub>NH<sub>2</sub>/KOH &rarr; &gt;CH<sub>2</sub> + N<sub>2</sub>&uarr;.<br>\n      <b style=\"color: #FFD600;\">&bull; Aldol:</b> 2 Carbonyls with &alpha;-H + dil. NaOH &rarr; &alpha;,&beta;-unsaturated carbonyl.<br>\n      <b style=\"color: #FFD600;\">&bull; Cannizzaro:</b> 2 Aldehydes (no &alpha;-H) + 50% NaOH &rarr; Alcohol + Carboxylate.<br>\n      <b style=\"color: #FFD600;\">&bull; HVZ:</b> RCH<sub>2</sub>COOH + X<sub>2</sub>/Red P &rarr; RCH(X)COOH.<br><br>\n\n      <b style=\"color: #FFD600; font-size: 16px; display: block; margin-bottom: 4px;\">2. Diagnostic Distinction Tests:</b>\n      <b style=\"color: #FFD600;\">&bull; Tollens&apos; Test:</b> Aldehydes give Silver Mirror; Ketones do not.<br>\n      <b style=\"color: #FFD600;\">&bull; Fehling&apos;s Test:</b> Aliphatic aldehydes give red Cu<sub>2</sub>O; Aromatic aldehydes &amp; ketones do not.<br>\n      <b style=\"color: #FFD600;\">&bull; 2,4-DNP Test:</b> All aldehydes &amp; ketones give orange/yellow precipitate.<br>\n      <b style=\"color: #FFD600;\">&bull; Iodoform Test:</b> CH<sub>3</sub>-C=O or CH<sub>3</sub>-CH(OH)- give yellow CHI<sub>3</sub> ppt.<br>\n      <b style=\"color: #FFD600;\">&bull; NaHCO<sub>3</sub> Test:</b> Carboxylic acids give brisk effervescence of CO<sub>2</sub>; Phenols/alcohols do not.\n    </div>\n  </div>\n\n</div>\n";

export const c12Chem8HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  <div style=\"background: rgba(255, 214, 0, 0.05); border: 1.5px solid #FFD600; border-radius: 12px; padding: 18px; margin-bottom: 25px; text-align: center;\">\n    <h2 class=\"text-center\" style=\"color: #FFD600; margin: 0 0 6px 0; font-size: 21px; font-weight: bold; text-align: center !important;\">\n      Class 12 Chemistry Unit VIII: Aldehydes, Ketones and Carboxylic Acids (08 Marks)\n    </h2>\n    <p class=\"text-center\" style=\"color: #FFD600; margin: 0; font-size: 15px; text-align: center !important;\">\n      Master 100 Board Standard Q&amp;A (Section A: 1-40 VSA &bull; Section B: 41-80 SA &bull; Section C: 81-100 LA Derivations)\n    </p>\n  </div>\n\n  <div style=\"background: rgba(255, 214, 0, 0.12); border-left: 5px solid #FFD600; padding: 12px 16px; margin: 30px 0 20px 0; border-radius: 6px;\">\n    <h2 style=\"color: #FFD600; margin: 0; font-size: 18px; font-weight: bold;\">Section A: Very Short Answer (VSA) Questions (1 Mark each)</h2>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q1: Define Carbonyl compounds and give the general formula for aliphatic aldehydes and ketones.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Compounds containing the carbonyl carbon-oxygen double bond (&gt;C=O). Aliphatic aldehydes and ketones share the general molecular formula <b>C<sub>n</sub>H<sub>2n</sub>O</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q2: What is the hybridisation and geometry of the carbonyl carbon atom in aldehydes and ketones?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>sp<sup>2</sup> hybridised</b> with a coplanar <b>trigonal planar geometry</b> and bond angles of approximately <b>120&deg;</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q3: Why is the dipole moment of aldehydes and ketones (2.3 - 2.8 D) higher than that of isomeric ethers?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because the carbonyl &pi;-electrons are loosely held and strongly shifted towards the more electronegative oxygen (&gt;C<sup>&delta;+</sup>=O<sup>&delta;-</sup>), creating substantial charge separation.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q4: Give the systematic IUPAC name of (CH<sub>3</sub>)<sub>2</sub>CH-CH<sub>2</sub>-CHO.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>3-Methylbutanal</b> (Common name: Isovaleraldehyde).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q5: Give the systematic IUPAC name of CH<sub>3</sub>-CH=CH-CHO.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>But-2-en-1-al</b> (Common name: Crotonaldehyde).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q6: Give the systematic IUPAC name of C<sub>6</sub>H<sub>5</sub>-CO-CH<sub>2</sub>CH<sub>3</sub>.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>1-Phenylpropan-1-one</b> (Common name: Propiophenone).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q7: Give the systematic IUPAC name of HOOC-CH<sub>2</sub>-CH(COOH)-CH<sub>2</sub>-COOH.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Propane-1,2,3-tricarboxylic acid</b> (When 3 or more -COOH groups are attached to an unbranched chain, none is included in the parent alkane name).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q8: State Rosenmund Reduction with complete chemical equation.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Catalytic hydrogenation of an acyl chloride over palladium supported on barium sulphate poisoned with quinoline/sulfur: <b>R-COCl + H<sub>2</sub> &rarr; (Pd - BaSO<sub>4</sub>) &rarr; R-CHO + HCl</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q9: What is the specific role of BaSO<sub>4</sub> (or sulfur/quinoline) in the Rosenmund reduction?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">It acts as a <b>catalyst poison</b> (moderator) that partially deactivates the Pd catalyst, preventing further reduction of the aldehyde into a primary alcohol.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q10: State Stephen Reaction with chemical equation.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Reduction of an alkyl/aryl nitrile with stannous chloride and conc. HCl followed by steam hydrolysis: <b>R-C&equiv;N + SnCl<sub>2</sub> + 2 HCl &rarr; R-CH=NH&bull;HCl &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; R-CHO + NH<sub>4</sub>Cl</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q11: What is DIBAL-H? State its major synthetic application.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Diisobutylaluminium hydride [(i-Bu)<sub>2</sub>AlH]</b>. It selectively reduces <b>nitriles and esters</b> to aldehydes at low temperatures (195 K) without reducing double bonds.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q12: Write the chemical equation for Etard reaction.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>C<sub>6</sub>H<sub>5</sub>CH<sub>3</sub> + 2 CrO<sub>2</sub>Cl<sub>2</sub> &rarr; (CS<sub>2</sub>) &rarr; C<sub>6</sub>H<sub>5</sub>CH(OCrOHCl<sub>2</sub>)<sub>2</sub> &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; C<sub>6</sub>H<sub>5</sub>CHO (Benzaldehyde)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q13: Write the chemical equation for Gattermann-Koch reaction.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>C<sub>6</sub>H<sub>6</sub> (Benzene) + CO + HCl &rarr; (anhyd. AlCl<sub>3</sub> / CuCl) &rarr; C<sub>6</sub>H<sub>5</sub>CHO (Benzaldehyde) + HCl</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q14: Why is dialkylcadmium (R<sub>2</sub>Cd) preferred over Grignard reagent for preparing ketones from acyl chlorides?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because dialkylcadmium is <b>less nucleophilic</b> than Grignard reagents and reacts readily with acyl chlorides to give ketones, but does not react further with the ketone formed.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q15: Why are aldehydes generally more reactive than ketones towards nucleophilic addition reactions?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Due to: (1) <b>Steric hindrance:</b> Aldehydes have only one alkyl group crowding the transition state, whereas ketones have two; (2) <b>Electronic factor:</b> Two electron-releasing (+I) alkyl groups in ketones reduce the partial positive charge on carbonyl carbon more than one alkyl group in aldehydes.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q16: Why is benzaldehyde less reactive than ethanal towards nucleophilic addition?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">In benzaldehyde, the carbonyl group is in resonance with the benzene ring (+R effect), which delocalizes &pi;-electrons into the carbonyl group, reducing the electrophilic positivity of the carbonyl carbon.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q17: Arrange in increasing order of reactivity towards nucleophilic addition: CH<sub>3</sub>COCH<sub>3</sub>, CH<sub>3</sub>CHO, HCHO, C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub>.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub> &lt; CH<sub>3</sub>COCH<sub>3</sub> &lt; CH<sub>3</sub>CHO &lt; HCHO</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q18: What is Tollens' reagent? What observation indicates a positive test?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Ammoniacal Silver Nitrate solution [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup>OH<sup>-</sup></b>. A positive test produces a <b>bright shiny Silver Mirror (Ag&darr;)</b> on the inner glass wall of the test tube.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q19: What is Fehling's solution? Which aldehydes reduce it?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">An alkaline solution containing copper(II) sulfate (Fehling A) and sodium potassium tartrate / Rochelle salt (Fehling B). <b>Only aliphatic aldehydes</b> reduce it to give a <b>red-brown precipitate of Cu<sub>2</sub>O&darr;</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q20: Why does Benzaldehyde give a positive Tollens' test but a negative Fehling's test?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Tollens' reagent is a stronger oxidizing agent than Fehling's solution. Benzaldehyde is less reactive than aliphatic aldehydes due to resonance stabilization and is not oxidized by the milder Fehling's reagent.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q21: What structural feature is necessary for an organic compound to give a positive Iodoform test?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Presence of a <b>CH<sub>3</sub>-C=O (methyl carbonyl) group</b> or a <b>CH<sub>3</sub>-CH(OH)- (methyl carbinol) group</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q22: Name one aldehyde and one ketone that give positive Iodoform tests.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Aldehyde: <b>Ethanal (Acetaldehyde, CH<sub>3</sub>CHO)</b>; Ketone: <b>Propan-2-one (Acetone, CH<sub>3</sub>COCH<sub>3</sub>)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q23: What reagent is used in Clemmensen Reduction? What is the product?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Amalgamated Zinc and concentrated HCl (Zn-Hg / conc. HCl)</b>. It reduces the carbonyl group (&gt;C=O) directly to a methylene group (<b>&gt;CH<sub>2</sub></b>).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q24: What reagents are used in Wolff-Kishner Reduction?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Hydrazine (NH<sub>2</sub>NH<sub>2</sub>) followed by heating with KOH (or potassium tert-butoxide) in ethylene glycol at 453-473 K</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q25: Why are &alpha;-hydrogens of aldehydes and ketones acidic in nature?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because: (1) The strongly electron-withdrawing (-I) carbonyl group polarizes the &alpha;-C-H bond, and (2) The conjugate base, <b>Enolate anion</b>, is stabilized by resonance over the electronegative carbonyl oxygen.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q26: What is the product formed when ethanal undergoes Aldol condensation followed by heating?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>But-2-en-1-al (Crotonaldehyde, CH<sub>3</sub>-CH=CH-CHO)</b>: 2 CH<sub>3</sub>CHO &rarr; (dil. NaOH) &rarr; CH<sub>3</sub>CH(OH)CH<sub>2</sub>CHO &rarr; (&Delta;) &rarr; CH<sub>3</sub>CH=CHCHO + H<sub>2</sub>O.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q27: Which aldehydes undergo Cannizzaro reaction?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Aldehydes that have <b>NO &alpha;-hydrogen atoms</b> (e.g. Formaldehyde HCHO, Benzaldehyde C<sub>6</sub>H<sub>5</sub>CHO, Trimethylacetaldehyde (CH<sub>3</sub>)<sub>3</sub>C-CHO).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q28: Write the chemical equation for the Cannizzaro reaction of Benzaldehyde.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>2 C<sub>6</sub>H<sub>5</sub>CHO + 50% KOH &rarr; C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>OH (Benzyl alcohol) + C<sub>6</sub>H<sub>5</sub>COOK (Potassium benzoate)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q29: What is Cross Cannizzaro reaction? Give an example.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Cannizzaro reaction between two different aldehydes with no &alpha;-H. When formaldehyde reacts with benzaldehyde: <b>HCHO + C<sub>6</sub>H<sub>5</sub>CHO + conc. NaOH &rarr; HCOONa (Sodium formate) + C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>OH (Benzyl alcohol)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q30: Why do carboxylic acids have higher boiling points than alcohols of comparable molecular weight?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because carboxylic acid molecules form strong, stable <b>intermolecular Hydrogen-Bonded Cyclic Dimers</b> involving two hydrogen bonds per dimer pair, even in the vapour phase.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q31: Write the chemical equation for the preparation of Benzoic acid from Toluene.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>C<sub>6</sub>H<sub>5</sub>CH<sub>3</sub> + 2 KMnO<sub>4</sub> + KOH &rarr; (&Delta;) &rarr; C<sub>6</sub>H<sub>5</sub>COOK &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; C<sub>6</sub>H<sub>5</sub>COOH (Benzoic acid) + MnO<sub>2</sub>&darr;</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q32: Why does tert-butylbenzene resist oxidation by alkaline KMnO<sub>4</sub> to benzoic acid?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because the benzylic carbon in tert-butylbenzene has <b>no benzylic &alpha;-hydrogen atom</b>, which is essential for initiating oxidative cleavage.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q33: Why are carboxylic acids more acidic than phenols?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because the <b>carboxylate ion (RCOO<sup>-</sup>)</b> is stabilized by two equivalent resonance structures where negative charge is delocalized over two highly electronegative oxygen atoms, whereas in phenoxide ion, negative charge is delocalized onto less electronegative carbon atoms with unequal resonance structures.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q34: Arrange in increasing order of acidity: CH<sub>3</sub>COOH, ClCH<sub>2</sub>COOH, FCH<sub>2</sub>COOH, CCl<sub>3</sub>COOH.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>CH<sub>3</sub>COOH &lt; ClCH<sub>2</sub>COOH &lt; FCH<sub>2</sub>COOH &lt; CCl<sub>3</sub>COOH</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q35: Why is Formic acid (HCOOH) stronger than Acetic acid (CH<sub>3</sub>COOH)?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">The methyl group in CH<sub>3</sub>COOH has an electron-releasing (+I) inductive effect which destabilizes the acetate anion, decreasing acidity. Formic acid has no alkyl group (pK<sub>a</sub> = 3.75 vs 4.76).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q36: What is the Ortho Effect in substituted benzoic acids?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Almost all <i>ortho</i>-substituted benzoic acids (e.g. <i>o</i>-toluic acid, <i>o</i>-nitrobenzoic acid) are stronger acids than benzoic acid regardless of the electronic nature of the substituent due to steric hindrance which twists the -COOH group out of the ring plane, preventing destabilizing ring resonance.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q37: State Hell-Volhard-Zelinsky (HVZ) reaction with chemical equation.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Carboxylic acids having &alpha;-hydrogens react with chlorine or bromine in the presence of catalytic red phosphorus: <b>R-CH<sub>2</sub>-COOH + X<sub>2</sub> / Red P &rarr; (H<sub>2</sub>O) &rarr; R-CH(X)-COOH (&alpha;-Halocarboxylic acid)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q38: Why does Formic acid not undergo HVZ reaction?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Because Formic acid (H-COOH) has <b>no &alpha;-carbon atom and no &alpha;-hydrogen</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q39: What product is obtained when sodium ethanoate is heated with soda-lime (NaOH + CaO)?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Methane (CH<sub>4</sub>)</b> via decarboxylation: CH<sub>3</sub>COONa + NaOH &rarr; (CaO / &Delta;) &rarr; CH<sub>4</sub> + Na<sub>2</sub>CO<sub>3</sub>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q40: How does sodium hydrogen carbonate (NaHCO<sub>3</sub>) distinguish between Acetic acid and Phenol?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Acetic acid</b> reacts with NaHCO<sub>3</sub> to give brisk effervescence of <b>CO<sub>2</sub>&uarr; gas</b> (CH<sub>3</sub>COOH + NaHCO<sub>3</sub> &rarr; CH<sub>3</sub>COONa + CO<sub>2</sub>&uarr; + H<sub>2</sub>O), whereas <b>Phenol is too weak an acid</b> to decompose NaHCO<sub>3</sub> and produces no effervescence.</p>\n  </div>\n\n  <div style=\"background: rgba(255, 214, 0, 0.12); border-left: 5px solid #FFD600; padding: 12px 16px; margin: 30px 0 20px 0; border-radius: 6px;\">\n    <h2 style=\"color: #FFD600; margin: 0; font-size: 18px; font-weight: bold;\">Section B: Short Answer (SA) Questions (2 &amp; 3 Marks each)</h2>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q41: Explain why aromatic aldehydes like Benzaldehyde do not reduce Fehling's solution while they reduce Tollens' reagent.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Tollens' reagent ([Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup>, E&deg; = +0.80 V) is a stronger oxidizing agent than Fehling's solution (Cu<sup>2+</sup> tartrate complex, E&deg; = +0.34 V). In benzaldehyde, conjugation of the carbonyl group with the benzene ring increases electron density on the carbonyl carbon via resonance (+R effect), making the C-H bond harder to oxidize. Hence, benzaldehyde is oxidized by Tollens' reagent to give silver mirror but cannot be oxidized by the milder Fehling's solution.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q42: How will you convert: (i) Toluene to Benzaldehyde, (ii) Benzene to Acetophenone?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Toluene &rarr; Benzaldehyde (Etard Reaction):</b> Toluene is treated with chromyl chloride (CrO<sub>2</sub>Cl<sub>2</sub>) in CS<sub>2</sub> to form a brown chromium complex C<sub>6</sub>H<sub>5</sub>CH(OCrOHCl<sub>2</sub>)<sub>2</sub>, which upon acidic hydrolysis yields Benzaldehyde.<br><b>(ii) Benzene &rarr; Acetophenone (Friedel-Crafts Acylation):</b> Benzene is heated with acetyl chloride (CH<sub>3</sub>COCl) or acetic anhydride in the presence of anhydrous AlCl<sub>3</sub> catalyst: C<sub>6</sub>H<sub>6</sub> + CH<sub>3</sub>COCl &rarr; (anhyd. AlCl<sub>3</sub>) &rarr; C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub> + HCl.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q43: Write the reaction and mechanism of addition of Sodium Bisulphite (NaHSO<sub>3</sub>) to Aldehydes and Methyl Ketones. What is its synthetic utility?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Carbonyl compound reacts with saturated aqueous NaHSO<sub>3</sub> via nucleophilic attack of bisulphite ion (SO<sub>3</sub><sup>2-</sup>) to form a crystalline <b>Bisulphite Addition Compound</b>: &gt;C=O + NaHSO<sub>3</sub> &#8652; &gt;C(OH)(SO<sub>3</sub>Na).<br><b>Synthetic Utility:</b> These bisulphite adducts are water-soluble crystalline solids. They are separated, purified, and then treated with dilute acid or base to regenerate pure carbonyl compounds, providing an excellent method for separation and purification of aldehydes and methyl ketones.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q44: Explain why only one -NH<sub>2</sub> group in Semicarbazide (H<sub>2</sub>N-NH-CONH<sub>2</sub>) acts as a nucleophile in reactions with aldehydes and ketones.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Semicarbazide possesses two -NH<sub>2</sub> groups: one attached directly to the hydrazine moiety (-NH-NH<sub>2</sub>) and one attached to the carbonyl amide moiety (-CO-NH<sub>2</sub>). The lone pair of electrons on the amide nitrogen is delocalized into the carbonyl group via resonance: H<sub>2</sub>N-NH-C(=O)-NH<sub>2</sub> &#8654; H<sub>2</sub>N-NH-C(O<sup>-</sup>)=N<sup>+</sup>H<sub>2</sub>. This resonance drastically reduces electron density on the amide nitrogen. In contrast, the hydrazine -NH<sub>2</sub> nitrogen lone pair is localized and fully available for nucleophilic attack.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q45: Distinguish between the following pairs using simple chemical tests: (i) Acetaldehyde and Benzaldehyde, (ii) Pentan-2-one and Pentan-3-one.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Acetaldehyde and Benzaldehyde:</b> Use <b>Fehling's test</b> or <b>Iodoform test</b>. Acetaldehyde (aliphatic, with CH<sub>3</sub>CO-) reduces Fehling's solution to give red Cu<sub>2</sub>O precipitate and forms yellow crystalline CHI<sub>3</sub> with I<sub>2</sub>/NaOH; Benzaldehyde gives negative results in both tests.<br><b>(ii) Pentan-2-one and Pentan-3-one:</b> Use <b>Iodoform test</b>: Pentan-2-one (a methyl ketone, CH<sub>3</sub>COCH<sub>2</sub>CH<sub>2</sub>CH<sub>3</sub>) forms a yellow precipitate of Iodoform (CHI<sub>3</sub>) with I<sub>2</sub>/NaOH, whereas Pentan-3-one does not.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q46: Explain Cross Aldol Condensation between Benzaldehyde and Acetophenone (Claisen-Schmidt reaction) with complete chemical equation.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">When an aromatic aldehyde with no &alpha;-hydrogen (Benzaldehyde) reacts with an aliphatic/aromatic ketone possessing &alpha;-hydrogens (Acetophenone) in the presence of dilute NaOH at room temperature followed by heating, condensation occurs to yield an <b>&alpha;,&beta;-unsaturated ketone (Chalcone / Benzalacetophenone)</b>:<br><b>C<sub>6</sub>H<sub>5</sub>-CHO + CH<sub>3</sub>-CO-C<sub>6</sub>H<sub>5</sub> &rarr; (dil. NaOH / &Delta;) &rarr; C<sub>6</sub>H<sub>5</sub>-CH=CH-CO-C<sub>6</sub>H<sub>5</sub> (Benzalacetophenone) + H<sub>2</sub>O</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q47: Why does Methanal (Formaldehyde) undergo Cannizzaro reaction while Ethanal undergoes Aldol condensation?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Ethanal (CH<sub>3</sub>CHO) possesses three acidic <b>&alpha;-hydrogen atoms</b> on its methyl carbon. Base abstracts an &alpha;-proton to form a resonance-stabilized enolate anion, which attacks another molecule of ethanal to initiate Aldol condensation. In contrast, Methanal (HCHO) has <b>no &alpha;-carbon and zero &alpha;-hydrogens</b>; base attacks the carbonyl carbon directly, triggering hydride transfer and disproportionation (Cannizzaro reaction).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q48: Explain the formation of Acetals and Cyclic Ketals as protecting groups for carbonyl compounds.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>1. Hemiacetals &amp; Acetals:</b> Aldehydes react with 1 mole of monohydric alcohol in dry HCl to form alkoxy alcohols (<b>Hemiacetals</b>), which react with a second mole of alcohol to yield gem-dialkoxy compounds (<b>Acetals</b>): RCHO + 2 R'OH &rarr; (dry HCl) &rarr; R-CH(OR')<sub>2</sub> + H<sub>2</sub>O.<br><b>2. Cyclic Ketals:</b> Ketones react with 1,2-diols (e.g. ethylene glycol) in dry HCl to yield <b>Cyclic Ethylene Glycol Ketals</b>. These acetals/ketals are stable to bases and nucleophiles, protecting carbonyl groups during multi-step organic synthesis, and can be readily hydrolyzed back to carbonyls with dilute aqueous acid.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q49: Arrange the following carboxylic acids in increasing order of acidic strength and explain: HCOOH, CH<sub>3</sub>COOH, ClCH<sub>2</sub>COOH, Cl<sub>2</sub>CHCOOH, CCl<sub>3</sub>COOH.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>CH<sub>3</sub>COOH &lt; HCOOH &lt; ClCH<sub>2</sub>COOH &lt; Cl<sub>2</sub>CHCOOH &lt; CCl<sub>3</sub>COOH</b>.<br><b>Reason:</b> Acetic acid is weaker than formic acid due to the electron-releasing (+I) effect of methyl group. Chlorine is an electron-withdrawing halogen (-I effect) which stabilizes the carboxylate anion by dispersing negative charge. As the number of chlorine atoms increases from 1 to 3, the cumulative -I inductive effect increases dramatically, stabilizing the conjugate base and sharply increasing acid strength (pK<sub>a</sub> of CCl<sub>3</sub>COOH = 0.65 vs CH<sub>3</sub>COOH = 4.76).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q50: Why is Benzoic acid stronger than Acetic acid, but weaker than Formic acid?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">In Benzoic acid (pK<sub>a</sub> = 4.20), the phenyl ring exerts a -I inductive effect (sp<sup>2</sup> carbon is more electronegative than sp<sup>3</sup> carbon in CH<sub>3</sub>COOH), making it stronger than acetic acid (pK<sub>a</sub> = 4.76). However, the phenyl ring also acts as an electron-donating group by resonance (+R effect), which partially destabilizes the carboxylate group relative to Formic acid (pK<sub>a</sub> = 3.75), which has no resonance destabilization.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q51: Explain the mechanism of Fischer Esterification of a carboxylic acid with an alcohol in presence of conc. H<sub>2</sub>SO<sub>4</sub>.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Step 1 (Protonation):</b> Protonation of the carbonyl oxygen by H<sub>2</sub>SO<sub>4</sub> enhances the electrophilicity of carbonyl carbon: R-COOH + H<sup>+</sup> &#8652; R-C<sup>+</sup>(OH)<sub>2</sub>.<br><b>Step 2 (Nucleophilic Attack):</b> Alcohol (R'OH) attacks the protonated carbonyl carbon to form a tetrahedral intermediate: [R-C(OH)<sub>2</sub>(O<sup>+</sup>HR')].<br><b>Step 3 (Proton Shift &amp; Water Loss):</b> Proton transfer from -O<sup>+</sup>HR' to -OH converts it into a good leaving group (-O<sup>+</sup>H<sub>2</sub>), which departs as neutral H<sub>2</sub>O.<br><b>Step 4 (Deprotonation):</b> Loss of H<sup>+</sup> gives the <b>Ester (R-COOR')</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q52: What happens when: (i) Acetic acid is treated with P<sub>2</sub>O<sub>5</sub> and heated, (ii) Ammonium acetate is heated strongly?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) With P<sub>2</sub>O<sub>5</sub>:</b> Two molecules of acetic acid undergo intermolecular dehydration to form <b>Acetic anhydride (Ethanoic anhydride)</b>: 2 CH<sub>3</sub>COOH &rarr; (P<sub>2</sub>O<sub>5</sub> / &Delta;) &rarr; (CH<sub>3</sub>CO)<sub>2</sub>O + H<sub>2</sub>O.<br><b>(ii) Strong heating of Ammonium Acetate:</b> Undergoes loss of water to form <b>Acetamide (Ethanamide)</b>: CH<sub>3</sub>COONH<sub>4</sub> &rarr; (&Delta;) &rarr; <b>CH<sub>3</sub>CONH<sub>2</sub></b> + H<sub>2</sub>O.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q53: How will you convert: (i) Benzoic acid to Benzamide, (ii) Phthalic acid to Phthalimide?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Benzoic acid &rarr; Benzamide:</b> React benzoic acid with ammonia to form ammonium benzoate, then heat strongly: C<sub>6</sub>H<sub>5</sub>COOH + NH<sub>3</sub> &#8652; C<sub>6</sub>H<sub>5</sub>COONH<sub>4</sub> &rarr; (&Delta;) &rarr; <b>C<sub>6</sub>H<sub>5</sub>CONH<sub>2</sub> (Benzamide)</b> + H<sub>2</sub>O.<br><b>(ii) Phthalic acid &rarr; Phthalimide:</b> React phthalic acid with NH<sub>3</sub> to form ammonium phthalate, heat moderately to form phthalamide, then heat strongly to eliminate NH<sub>3</sub> yielding <b>Phthalimide</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q54: Describe the Hell-Volhard-Zelinsky (HVZ) reaction: conditions, reagents, mechanism, and synthetic importance.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Reagents &amp; Conditions:</b> Aliphatic carboxylic acid with &alpha;-hydrogen is treated with Br<sub>2</sub> or Cl<sub>2</sub> in the presence of catalytic Red Phosphorus at 373 K followed by water workup.<br><b>Equation:</b> CH<sub>3</sub>CH<sub>2</sub>COOH + Br<sub>2</sub> / Red P &rarr; (H<sub>2</sub>O) &rarr; <b>CH<sub>3</sub>CH(Br)COOH (2-Bromopropanoic acid)</b> + HBr.<br><b>Importance:</b> Introduces halogen selectively at &alpha;-position. &alpha;-Bromo acids can be readily converted into &alpha;-hydroxy acids (lactic acid) by aq. KOH or &alpha;-amino acids (alanine) by excess NH<sub>3</sub>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q55: Why does electrophilic aromatic substitution in Benzoic acid occur at the meta position, and why does Benzoic acid not undergo Friedel-Crafts reaction?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">The carboxyl group (-COOH) is strongly electron-withdrawing by both -I (inductive) and -M (resonance) effects. Canonical structures show positive charge at ortho and para positions, leaving the <b>meta position comparatively higher in electron density</b>. Hence, incoming electrophiles attack at the meta position (e.g. nitration gives <i>m</i>-nitrobenzoic acid).<br><b>No Friedel-Crafts Reaction:</b> The -COOH group is strongly deactivating and the catalyst anhydrous AlCl<sub>3</sub> (Lewis acid) complexes strongly with the carboxyl oxygen lone pairs, making the ring completely unreactive.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q56: An organic compound A (C<sub>3</sub>H<sub>6</sub>O) gives a positive 2,4-DNP test and a positive Iodoform test, but does not reduce Tollens' reagent. Identify A and write all reactions.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Identification:</b> Since A (C<sub>3</sub>H<sub>6</sub>O) gives positive 2,4-DNP, it has a carbonyl group. Since it does NOT reduce Tollens' reagent, it is a <b>ketone</b>. Since it gives a positive Iodoform test, it must be a methyl ketone.<br><b>Compound A:</b> <b>Propan-2-one (Acetone, CH<sub>3</sub>COCH<sub>3</sub>)</b>.<br><b>Reactions:</b><br>1. CH<sub>3</sub>COCH<sub>3</sub> + 2,4-DNP &rarr; Acetone 2,4-dinitrophenylhydrazone (yellow-orange ppt).<br>2. CH<sub>3</sub>COCH<sub>3</sub> + 3 I<sub>2</sub> + 4 NaOH &rarr; <b>CHI<sub>3</sub>&darr; (Yellow Iodoform)</b> + CH<sub>3</sub>COONa + 3 NaI + 3 H<sub>2</sub>O.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q57: An organic compound A (C<sub>8</sub>H<sub>8</sub>O) forms an orange-red precipitate with 2,4-DNP and gives a yellow precipitate with I<sub>2</sub>/NaOH. It does not reduce Tollens' or Fehling's reagent, nor does it decolourise bromine water. On drastic oxidation with chromic acid, it gives a carboxylic acid B (C<sub>7</sub>H<sub>6</sub>O<sub>2</sub>). Identify A and B.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Compound A:</b> <b>Acetophenone (1-Phenylethan-1-one, C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub>)</b> (methyl ketone, reacts with 2,4-DNP and I<sub>2</sub>/NaOH, no reduction of Tollens'/Fehling's).<br><b>Compound B:</b> <b>Benzoic acid (C<sub>6</sub>H<sub>5</sub>COOH)</b> (drastic oxidation of acetophenone yields benzoic acid).<br><b>Reaction:</b> C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub> + 3 I<sub>2</sub> + 4 NaOH &rarr; CHI<sub>3</sub>&darr; + C<sub>6</sub>H<sub>5</sub>COONa.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q58: Explain the industrial preparation and important commercial uses of Formaldehyde and Acetaldehyde.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>1. Formaldehyde (HCHO):</b> Prepared industrially by catalytic aerial oxidation of methanol over silver or iron oxide-molybdenum oxide catalyst at 573-673 K: 2 CH<sub>3</sub>OH + O<sub>2</sub> &rarr; (Ag / 573 K) &rarr; 2 HCHO + 2 H<sub>2</sub>O. <b>Uses:</b> 40% aqueous solution is known as <b>Formalin</b> (used for preserving biological specimens), manufacture of Bakelite and urea-formaldehyde resins.<br><b>2. Acetaldehyde (CH<sub>3</sub>CHO):</b> Manufactured by Wacker process (oxidation of ethene with PdCl<sub>2</sub>-CuCl<sub>2</sub> in water). <b>Uses:</b> Manufacture of acetic acid, ethyl acetate, and pyridine.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q59: How will you distinguish between: (i) Benzaldehyde and Acetophenone, (ii) Benzoic acid and Ethyl benzoate?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Benzaldehyde and Acetophenone:</b> <b>Tollens' Test:</b> Benzaldehyde reduces Tollens' reagent giving a silver mirror; Acetophenone gives no reaction. Alternatively, <b>Iodoform test:</b> Acetophenone gives yellow CHI<sub>3</sub> precipitate; Benzaldehyde does not.<br><b>(ii) Benzoic acid and Ethyl benzoate:</b> <b>Sodium bicarbonate test:</b> Benzoic acid produces brisk effervescence of CO<sub>2</sub> with aqueous NaHCO<sub>3</sub>; Ethyl benzoate (an ester) does not react.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q60: Explain Popoff's Rule for the oxidation of unsymmetrical ketones with an example.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">During the vigorous oxidation of unsymmetrical ketones (using hot conc. HNO<sub>3</sub> or acidified KMnO<sub>4</sub>), the carbon-carbon bond on either side of the carbonyl group cleaves such that <b>the carbonyl group (&gt;C=O) predominantly stays with the smaller alkyl group</b>.<br><i>Example:</i> Oxidation of Butan-2-one (CH<sub>3</sub>-CO-CH<sub>2</sub>CH<sub>3</sub>) yields predominantly <b>2 molecules of Ethanoic acid (CH<sub>3</sub>COOH)</b> because the keto group stays with the smaller methyl group.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q61: Why does Propanal have a higher boiling point (49 &deg;C) than Butane (0 &deg;C) but lower than Propan-1-ol (97 &deg;C)?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Propanal (MW 58) has strong <b>intermolecular dipole-dipole attractions</b> due to polar &gt;C=O bond, giving it a higher boiling point than non-polar butane (MW 58, only weak dispersion forces). However, propanal cannot form intermolecular hydrogen bonds with itself because oxygen is not bonded to hydrogen, whereas propan-1-ol forms strong <b>intermolecular Hydrogen Bonds</b>, resulting in a much higher boiling point.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q62: Explain the mechanism of nucleophilic addition of HCN to Ethanal in the presence of a base catalyst.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Step 1 (Generation of Nucleophile):</b> HCN is a weak acid; base (OH<sup>-</sup>) deprotonates HCN to generate the strong nucleophile <b>Cyanide ion (CN<sup>-</sup>)</b>: HCN + OH<sup>-</sup> &#8652; CN<sup>-</sup> + H<sub>2</sub>O.<br><b>Step 2 (Nucleophilic Attack):</b> CN<sup>-</sup> attacks the electrophilic carbonyl carbon of ethanal forming a tetrahedral alkoxide: CH<sub>3</sub>CHO + CN<sup>-</sup> &rarr; (Slow) &rarr; CH<sub>3</sub>CH(CN)O<sup>-</sup>.<br><b>Step 3 (Protonation):</b> Alkoxide abstracts H<sup>+</sup> from water/HCN to give <b>Acetaldehyde Cyanohydrin [2-hydroxypropanenitrile, CH<sub>3</sub>CH(OH)CN]</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q63: Give reasons: (i) Monochloroacetic acid is stronger than acetic acid, (ii) Fluoroacetic acid is stronger than chloroacetic acid.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Monochloroacetic vs Acetic:</b> Chlorine has an electron-withdrawing inductive effect (-I) which delocalizes negative charge in chloroacetate ion, stabilizing it relative to acetate ion.<br><b>(ii) Fluoroacetic vs Chloroacetic:</b> Fluorine is more electronegative than Chlorine, exerting a much stronger -I effect and stabilizing the conjugate base more effectively, making fluoroacetic acid (pK<sub>a</sub> = 2.59) stronger than chloroacetic acid (pK<sub>a</sub> = 2.87).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q64: Give reasons: (i) Benzaldehyde does not undergo Aldol condensation, (ii) Acetic acid does not give positive Tollens' test.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Benzaldehyde:</b> Lacks &alpha;-hydrogen atoms on the carbonyl adjacent carbon; hence, cannot form an enolate ion required for aldol condensation.<br><b>(ii) Acetic Acid:</b> Has no free aldehyde (-CHO) group; the carbonyl carbon is bonded to -OH which donates electrons by resonance, making the carboxyl carbon non-reducing toward weak oxidizing agents like Tollens' reagent.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q65: How will you convert: (i) Ethanal to But-2-enal, (ii) Ethanal to Butane-1,3-diol, (iii) Ethanal to But-2-enoic acid?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Ethanal &rarr; But-2-enal:</b> Dilute NaOH (Aldol addition) &rarr; 3-Hydroxybutanal &rarr; heat with acid (&Delta;, -H<sub>2</sub>O) &rarr; <b>CH<sub>3</sub>-CH=CH-CHO (But-2-enal)</b>.<br><b>(ii) Ethanal &rarr; Butane-1,3-diol:</b> Aldol addition of ethanal with dil. NaOH yields 3-hydroxybutanal, which on reduction with NaBH<sub>4</sub> yields <b>CH<sub>3</sub>-CH(OH)-CH<sub>2</sub>-CH<sub>2</sub>OH (Butane-1,3-diol)</b>.<br><b>(iii) Ethanal &rarr; But-2-enoic acid:</b> Dehydrate aldol to But-2-enal, then selectively oxidize with mild Tollens' reagent [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> to obtain <b>CH<sub>3</sub>-CH=CH-COOH (But-2-enoic acid / Crotonic acid)</b> without attacking the C=C double bond.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q66: How will you convert: (i) Acetone to Mesityl Oxide, (ii) Acetone to Phorone?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Acetone &rarr; Mesityl Oxide:</b> Two molecules of acetone undergo aldol condensation in presence of dry HCl gas or Ba(OH)<sub>2</sub> to give 4-hydroxy-4-methylpentan-2-one (Diacetone alcohol), which on heating loses water to yield <b>Mesityl oxide [4-methylpent-3-en-2-one, (CH<sub>3</sub>)<sub>2</sub>C=CH-COCH<sub>3</sub>]</b>.<br><b>(ii) Acetone &rarr; Phorone:</b> Three molecules of acetone condense in presence of dry HCl gas with loss of 2 molecules of water to form <b>Phorone [(CH<sub>3</sub>)<sub>2</sub>C=CH-CO-CH=C(CH<sub>3</sub>)<sub>2</sub>, 2,6-dimethylhepta-2,5-dien-4-one]</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q67: Explain the reaction of aldehydes and ketones with Grignard reagents to yield 1&deg;, 2&deg;, and 3&deg; alcohols.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Grignard reagent (RMgX) adds nucleophilically across the carbonyl C=O double bond: &gt;C=O + RMgX &rarr; &gt;C(R)-OMgX &rarr; (H<sub>3</sub>O<sup>+</sup>) &rarr; &gt;C(R)-OH + Mg(OH)X.<br><b>1. Formaldehyde (HCHO) + RMgX &rarr; Primary (1&deg;) Alcohol (R-CH<sub>2</sub>OH)</b>.<br><b>2. Other Aldehydes (R'CHO) + RMgX &rarr; Secondary (2&deg;) Alcohol (R'-CH(OH)-R)</b>.<br><b>3. Ketones (R'COR'') + RMgX &rarr; Tertiary (3&deg;) Alcohol (R'R''C(OH)R)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q68: What is the action of: (i) LiAlH<sub>4</sub> on Acetic acid, (ii) B<sub>2</sub>H<sub>6</sub> on Benzoic acid, (iii) NaBH<sub>4</sub> on Acetic acid?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) LiAlH<sub>4</sub> on Acetic acid:</b> Reduces it completely to <b>Ethanol (CH<sub>3</sub>CH<sub>2</sub>OH)</b>.<br><b>(ii) B<sub>2</sub>H<sub>6</sub> on Benzoic acid:</b> Diborane in THF selectively and rapidly reduces carboxylic acids to primary alcohols, yielding <b>Benzyl alcohol (C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>OH)</b>.<br><b>(iii) NaBH<sub>4</sub> on Acetic acid:</b> <b>No reaction</b> (Sodium borohydride is a milder hydride donor and does not reduce carboxylic acid groups).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q69: Why do carboxylic acids not undergo typical nucleophilic addition reactions characteristic of aldehydes and ketones?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">In carboxylic acids, the lone pairs of electrons on the hydroxyl oxygen undergo resonance with the carbonyl group: R-C(=O)-OH &#8654; R-C(O<sup>-</sup>)=O<sup>+</sup>H. This resonance significantly decreases the partial positive charge on the carbonyl carbon, making it far less electrophilic than in aldehydes and ketones.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q70: What is Formic acid reducing property? Why does Formic acid reduce Tollens' reagent and Fehling's solution while Acetic acid does not?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Formic acid structure (<b>H-CO-OH</b>) uniquely contains both an <b>aldehyde group (-CHO)</b> and a carboxyl group (-COOH). Because of the presence of the aldehydic hydrogen bonded directly to carbonyl carbon, Formic acid readily acts as a reducing agent, reducing Tollens' reagent to Ag mirror and Fehling's solution to red Cu<sub>2</sub>O, whereas Acetic acid (CH<sub>3</sub>COOH) has a methyl group and cannot act as a reducing agent.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q71: Convert: (i) Bromobenzene to Benzoic acid, (ii) Ethylbenzene to Benzoic acid, (iii) Acetophenone to Benzoic acid.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Bromobenzene &rarr; Benzoic acid:</b> React with Mg in dry ether to form Phenylmagnesium bromide (C<sub>6</sub>H<sub>5</sub>MgBr), react with solid CO<sub>2</sub> (dry ice), followed by acidic hydrolysis &rarr; C<sub>6</sub>H<sub>5</sub>COOH.<br><b>(ii) Ethylbenzene &rarr; Benzoic acid:</b> Heat with alkaline KMnO<sub>4</sub>/KOH followed by acidification with dil. H<sub>2</sub>SO<sub>4</sub> &rarr; C<sub>6</sub>H<sub>5</sub>COOH.<br><b>(iii) Acetophenone &rarr; Benzoic acid:</b> Haloform reaction with I<sub>2</sub>/NaOH yields Sodium benzoate + CHI<sub>3</sub>&darr;, followed by acidification with HCl &rarr; C<sub>6</sub>H<sub>5</sub>COOH.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q72: Write IUPAC names of: (i) Acrolein, (ii) Cinnamaldehyde, (iii) Phthalaldehyde, (iv) Vanillin.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Acrolein (CH<sub>2</sub>=CH-CHO):</b> Prop-2-en-1-al.<br><b>(ii) Cinnamaldehyde (C<sub>6</sub>H<sub>5</sub>-CH=CH-CHO):</b> 3-Phenylprop-2-en-1-al.<br><b>(iii) Phthalaldehyde:</b> Benzene-1,2-dicarbaldehyde.<br><b>(iv) Vanillin:</b> 4-Hydroxy-3-methoxybenzaldehyde.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q73: How will you convert: (i) Benzaldehyde to Cinnamic acid (Perkin Reaction), (ii) Benzaldehyde to Benzoin (Benzoin Condensation)?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Benzaldehyde &rarr; Cinnamic acid (Perkin Reaction):</b> Heat Benzaldehyde with acetic anhydride in the presence of sodium acetate at 453 K: C<sub>6</sub>H<sub>5</sub>CHO + (CH<sub>3</sub>CO)<sub>2</sub>O &rarr; (CH<sub>3</sub>COONa / 453 K) &rarr; <b>C<sub>6</sub>H<sub>5</sub>-CH=CH-COOH (Cinnamic acid)</b> + CH<sub>3</sub>COOH.<br><b>(ii) Benzaldehyde &rarr; Benzoin (Benzoin Condensation):</b> Reflux two molecules of benzaldehyde with ethanolic KCN solution: 2 C<sub>6</sub>H<sub>5</sub>CHO &rarr; (alc. KCN) &rarr; <b>C<sub>6</sub>H<sub>5</sub>-CH(OH)-CO-C<sub>6</sub>H<sub>5</sub> (Benzoin)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q74: Explain the relative acidic strengths of: o-Nitrobenzoic acid, m-Nitrobenzoic acid, p-Nitrobenzoic acid, and Benzoic acid.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>o-Nitrobenzoic acid &gt; p-Nitrobenzoic acid &gt; m-Nitrobenzoic acid &gt; Benzoic acid</b>.<br><b>Explanation:</b> <i>o</i>-Nitrobenzoic acid is strongest due to the <b>ortho effect</b> (steric inhibition of ring resonance). At <i>para</i> position, -NO<sub>2</sub> exerts strong electron-withdrawing -I and -M effects, stabilizing the benzoate anion. At <i>meta</i> position, only the weaker -I effect operates without resonance (-M) stabilization.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q75: Write short notes on: (i) Rosenmund Reduction, (ii) Clemmensen Reduction.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Rosenmund Reduction:</b> Selective catalytic hydrogenation of an acyl chloride to an aldehyde using H<sub>2</sub> over Pd supported on BaSO<sub>4</sub> (poisoned with quinoline or sulfur) in boiling xylene.<br><b>(ii) Clemmensen Reduction:</b> Deoxygenation of an aldehyde or ketone to a hydrocarbon (-CH<sub>2</sub>-) by heating with amalgamated zinc (Zn-Hg) and concentrated hydrochloric acid.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q76: Write short notes on: (i) Wolff-Kishner Reduction, (ii) Etard Reaction.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>(i) Wolff-Kishner Reduction:</b> Conversion of a carbonyl group to methylene group (-CH<sub>2</sub>-) by treating with hydrazine (NH<sub>2</sub>NH<sub>2</sub>) followed by heating with strong base (KOH) in high-boiling ethylene glycol at 453-473 K.<br><b>(ii) Etard Reaction:</b> Mild oxidation of toluene to benzaldehyde using chromyl chloride (CrO<sub>2</sub>Cl<sub>2</sub>) in non-polar CS<sub>2</sub> or CCl<sub>4</sub> to form a brown coordination complex, followed by aqueous hydrolysis.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q77: Why does Methanoic acid (Formic acid) give a silver mirror with Tollens' reagent while Ethanoic acid does not?\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Methanoic acid (H-COOH) contains a formyl hydrogen atom directly bonded to the carbonyl group (having an oxidizable -CHO fragment). It undergoes oxidation to carbonic acid (H<sub>2</sub>CO<sub>3</sub> &rarr; CO<sub>2</sub> + H<sub>2</sub>O) while reducing Tollens' reagent to Ag. Ethanoic acid (CH<sub>3</sub>COOH) has a methyl group and lacks this aldehydic feature.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q78: What is Kolbe's Electrolytic Decarboxylation? Give equation for sodium acetate.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\">Electrolysis of a concentrated aqueous solution of sodium or potassium carboxylate yields a symmetrical alkane at the anode: <b>2 CH<sub>3</sub>COONa + 2 H<sub>2</sub>O &rarr; (Electrolysis) &rarr; CH<sub>3</sub>-CH<sub>3</sub> (Ethane at anode) + 2 CO<sub>2</sub>&uarr; + 2 NaOH + H<sub>2</sub>&uarr; (at cathode)</b>.</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q79: An organic compound A (C<sub>5</sub>H<sub>10</sub>O) gives a positive 2,4-DNP test, reduces Tollens' reagent, and on oxidation yields B (C<sub>5</sub>H<sub>10</sub>O<sub>2</sub>). A on Clemmensen reduction yields pentane. Identify A and B.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Compound A:</b> <b>Pentanal (CH<sub>3</sub>CH<sub>2</sub>CH<sub>2</sub>CH<sub>2</sub>CHO)</b> (gives 2,4-DNP, reduces Tollens', Clemmensen reduction yields n-pentane).<br><b>Compound B:</b> <b>Pentanoic acid (CH<sub>3</sub>CH<sub>2</sub>CH<sub>2</sub>CH<sub>2</sub>COOH)</b> (oxidation of 1&deg; aldehyde).</p>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q80: Compare the reactivity of Carbonyl group in Aldehydes/Ketones vs Carboxylic acids vs Esters towards nucleophilic attack.\n    </h3>\n    <p style=\"color: #FFFFFF; line-height: 1.7; font-size: 15.5px;\"><b>Aldehydes &gt; Ketones &gt; Esters &gt; Carboxylic Acids &gt; Amides</b>.<br>In esters, acids, and amides, the heteroatom (O, N) donates its lone pair into the carbonyl carbon via resonance (+R / +M effect), substantially dispersing the partial positive charge and diminishing electrophilicity compared to aldehydes and ketones.</p>\n  </div>\n\n  <div style=\"background: rgba(255, 214, 0, 0.12); border-left: 5px solid #FFD600; padding: 12px 16px; margin: 30px 0 20px 0; border-radius: 6px;\">\n    <h2 style=\"color: #FFD600; margin: 0; font-size: 18px; font-weight: bold;\">Section C: Long Answer (LA) Questions &amp; Derivations (5 Marks each)</h2>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q81: Give the complete step-by-step mechanism for the Nucleophilic Addition Reaction to Carbonyl Group (&gt;C=O) under neutral and acid-catalysed conditions.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Base-Catalysed / Neutral Pathway (Direct Nucleophilic Attack):</b><br><b>Step 1: Attack of Nucleophile (Slow, Rate-Determining Step - RDS)</b><br>A strong nucleophile (Nu<sup>-</sup>) attacks the electrophilic sp<sup>2</sup> hybridised carbonyl carbon from a trajectory perpendicular to the plane of the carbonyl group (B&uuml;rgi-Dunitz angle &approx; 107&deg;). The &pi;-bond pair shifts completely onto oxygen, converting planar sp<sup>2</sup> carbon into a tetrahedral alkoxide intermediate (sp<sup>3</sup>):<br>&gt;C=O (Planar sp<sup>2</sup>) + Nu<sup>-</sup> &rarr; (Slow, RDS) &rarr; &gt;C(Nu)-O<sup>-</sup> (Tetrahedral Intermediate sp<sup>3</sup>).<br><br><b>Step 2: Proton Transfer (Fast Step)</b><br>The alkoxide intermediate abstracts a proton (H<sup>+</sup>) from the solvent/conjugate acid to yield the neutral addition product:<br>&gt;C(Nu)-O<sup>-</sup> + H<sup>+</sup> &rarr; (Fast) &rarr; &gt;C(Nu)-OH.<br><br><b>2. Acid-Catalysed Pathway (for Weak Nucleophiles like ROH, H<sub>2</sub>O):</b><br><b>Step 1: Protonation of Carbonyl Oxygen:</b> &gt;C=O + H<sup>+</sup> &#8652; &gt;C=O<sup>+</sup>-H &#8654; &gt;C<sup>+</sup>-OH. (Protonation creates full carbocationic character on carbon, making it extraordinarily electrophilic).<br><b>Step 2: Attack of Weak Nucleophile:</b> Weak neutral nucleophile (:Nu-H) attacks the carbocation.<br><b>Step 3: Deprotonation:</b> Loss of H<sup>+</sup> regenerates the acid catalyst and yields the addition product.<br><br><b>Reactivity Hierarchy:</b> HCHO &gt; RCHO &gt; R-CO-R' &gt; ArCHO &gt; Ar-CO-R.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q82: Detail the complete step-by-step mechanism of Base-Catalysed Aldol Condensation of Ethanal to form But-2-enal.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Overall Reaction:</b> 2 CH<sub>3</sub>CHO &rarr; (dil. NaOH) &rarr; CH<sub>3</sub>CH(OH)CH<sub>2</sub>CHO (Aldol) &rarr; (&Delta;, -H<sub>2</sub>O) &rarr; CH<sub>3</sub>-CH=CH-CHO (But-2-enal).<br><br><b>Step 1: Generation of Enolate Anion (Acid-Base Reaction)</b><br>The base (OH<sup>-</sup>) abstracts an acidic &alpha;-proton from one molecule of ethanal to generate a resonance-stabilized enolate ion (nucleophile):<br>H-CH<sub>2</sub>-CHO + OH<sup>-</sup> &#8652; [<sup>-</sup>:CH<sub>2</sub>-CHO &#8654; CH<sub>2</sub>=CH-O<sup>-</sup>] (Enolate Anion) + H<sub>2</sub>O.<br><br><b>Step 2: Nucleophilic Attack on Second Carbonyl Molecule (RDS)</b><br>The carbanionic center of the enolate attacks the electrophilic carbonyl carbon of a second ethanal molecule to form an alkoxide intermediate:<br>CH<sub>3</sub>-C(=O)H + :CH<sub>2</sub>-CHO &rarr; (Slow) &rarr; CH<sub>3</sub>-CH(O<sup>-</sup>)-CH<sub>2</sub>-CHO.<br><br><b>Step 3: Protonation to form Aldol (Fast Step)</b><br>The alkoxide intermediate removes a proton from water, forming 3-hydroxybutanal (Aldol) and regenerating OH<sup>-</sup>:<br>CH<sub>3</sub>-CH(O<sup>-</sup>)-CH<sub>2</sub>-CHO + H<sub>2</sub>O &#8652; CH<sub>3</sub>-CH(OH)-CH<sub>2</sub>-CHO (Aldol) + OH<sup>-</sup>.<br><br><b>Step 4: Dehydration (Elimination upon Heating)</b><br>Upon heating, loss of water occurs via E1cB pathway to give the stable conjugated <b>But-2-enal (Crotonaldehyde, CH<sub>3</sub>-CH=CH-CHO)</b>.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q83: Detail the complete mechanism of the Cannizzaro Reaction of Formaldehyde with concentrated alkali.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Overall Reaction:</b> 2 HCHO + conc. NaOH &rarr; CH<sub>3</sub>OH (Methanol) + HCOONa (Sodium formate).<br><br><b>Step 1: Nucleophilic Attack by Hydroxide Ion on Carbonyl Carbon (Fast Equilibrium)</b><br>Hydroxide ion (OH<sup>-</sup>) attacks the carbonyl carbon of formaldehyde to produce a dianionic/monoanionic tetrahedral intermediate:<br>H-CHO + OH<sup>-</sup> &#8652; H-CH(OH)-O<sup>-</sup>.<br><br><b>Step 2: Hydride Ion Transfer (Slow, Rate-Determining Step - RDS)</b><br>The alkoxide intermediate collapses its C-O<sup>-</sup> bond to regenerate C=O, expelling a <b>hydride ion (:H<sup>-</sup>)</b> which directly attacks the carbonyl carbon of a second formaldehyde molecule:<br>H-C(=O)OH + H-CH(O<sup>-</sup>)-H &rarr; (Slow, Hydride Transfer) &rarr; H-COOH (Formic acid) + CH<sub>3</sub>-O<sup>-</sup> (Methoxide ion).<br><br><b>Step 3: Rapid Acid-Base Proton Transfer (Fast Step)</b><br>Methoxide ion (a strong base) rapidly abstracts the acidic proton from formic acid:<br>H-COOH + CH<sub>3</sub>O<sup>-</sup> &rarr; (Fast) &rarr; <b>HCOO<sup>-</sup> (Formate ion) + CH<sub>3</sub>OH (Methanol)</b>.<br><br><b>Kinetics:</b> Rate = k [HCHO]<sup>2</sup> [OH<sup>-</sup>] (Third-order reaction in moderately concentrated base).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q84: Comprehensive comparative analysis of named deoxygenation reductions: Clemmensen Reduction vs Wolff-Kishner Reduction.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Clemmensen Reduction:</b><br>&bull; <b>Reagents:</b> Amalgamated Zinc and concentrated hydrochloric acid (<b>Zn-Hg / conc. HCl</b>).<br>&bull; <b>Reaction:</b> &gt;C=O + 4 [H] &rarr; &gt;CH<sub>2</sub> + H<sub>2</sub>O.<br>&bull; <b>Mechanism:</b> Involves electron transfer from zinc surface to protonated carbonyl, forming organozinc carbanion intermediates on the metal surface.<br>&bull; <b>Limitation / Trap:</b> Fails for substrates containing <b>acid-sensitive groups</b> (e.g. acetals, ethers, -OH groups which dehydrate, or C=C double bonds which add HCl).<br><br><b>2. Wolff-Kishner Reduction:</b><br>&bull; <b>Reagents:</b> Hydrazine (NH<sub>2</sub>NH<sub>2</sub>) followed by heating with <b>KOH in high-boiling Ethylene glycol at 453-473 K</b>.<br>&bull; <b>Reaction:</b> &gt;C=O + NH<sub>2</sub>NH<sub>2</sub> &rarr; &gt;C=N-NH<sub>2</sub> (Hydrazone) &rarr; (KOH / Glycol / &Delta;) &rarr; &gt;CH<sub>2</sub> + N<sub>2</sub>&uarr;.<br>&bull; <b>Mechanism:</b> Base deprotonates hydrazone to form resonance-stabilized azo-anion, which eliminates nitrogen gas (N<sub>2</sub>) driving the reaction to completion.<br>&bull; <b>Limitation / Trap:</b> Fails for substrates containing <b>base-sensitive groups</b> (e.g. esters, lactones, alkyl halides which undergo E2 elimination).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q85: Comprehensive study of the Iodoform (Haloform) Reaction: Structural requirements, mechanism, and analytical applications.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Structural Requirement:</b> Organic compounds containing either a <b>methyl ketone group (CH<sub>3</sub>-C=O)</b> or a <b>methyl carbinol group (CH<sub>3</sub>-CH(OH)-)</b> that oxidizes in situ to a methyl ketone.<br><br><b>2. Reagents &amp; Overall Reaction:</b><br>R-CO-CH<sub>3</sub> + 3 I<sub>2</sub> + 4 NaOH &rarr; <b>CHI<sub>3</sub>&darr; (Yellow Iodoform ppt)</b> + R-COONa + 3 NaI + 3 H<sub>2</sub>O.<br><br><b>3. Step-by-Step Mechanism:</b><br>&bull; <b>Step 1 (Trihalogenation):</b> Base abstracts acidic &alpha;-protons sequentially; each carbanion reacts with I<sub>2</sub> to form triiodo derivative: R-CO-CH<sub>3</sub> + 3 I<sub>2</sub> + 3 OH<sup>-</sup> &rarr; <b>R-CO-CI<sub>3</sub> (Triiodomethyl ketone)</b> + 3 I<sup>-</sup> + 3 H<sub>2</sub>O.<br>&bull; <b>Step 2 (Nucleophilic Cleavage):</b> OH<sup>-</sup> attacks carbonyl carbon of R-CO-CI<sub>3</sub>, forming a tetrahedral intermediate which expels the stabilized <b>:C<sup>-</sup>I<sub>3</sub> (Triiodomethyl carbanion)</b>.<br>&bull; <b>Step 3 (Proton Transfer):</b> RCOOH + :C<sup>-</sup>I<sub>3</sub> &rarr; <b>RCOO<sup>-</sup> + CHI<sub>3</sub>&darr;</b>.<br><br><b>4. Analytical Applications:</b> Distinguishes ethanal from other aldehydes; distinguishes pentan-2-one from pentan-3-one; distinguishes ethanol from methanol.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q86: Draw the resonance structures of Carboxylic Acids and Carboxylate Anion. Explain the profound origin of acidity in Carboxylic Acids.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Resonance in Undissociated Carboxylic Acid (R-COOH):</b><br>R-C(=O)-OH &#8654; R-C(O<sup>-</sup>)=O<sup>+</sup>H.<br>These resonance structures involve <b>charge separation</b> (+ on oxygen, - on other oxygen), making them higher in energy and less stable.<br><br><b>2. Resonance in Carboxylate Anion (R-COO<sup>-</sup>):</b><br>[R-C(=O)-O<sup>-</sup> &#8654; R-C(O<sup>-</sup>)=O].<br>The conjugate base possesses <b>two completely equivalent canonical structures</b> where negative charge is evenly delocalized across two highly electronegative oxygen atoms with identical C-O bond lengths (127 pm, intermediate between single and double bond).<br><br><b>3. Comparison with Phenol:</b> In phenoxide ion, the negative charge is delocalized over carbon atoms of the benzene ring (which are less electronegative than oxygen) and canonical structures are non-equivalent. Hence, carboxylate ion is far more stabilized than phenoxide ion, making carboxylic acids much stronger acids (pK<sub>a</sub> &approx; 4-5 vs pK<sub>a</sub> &approx; 10 for phenol).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q87: Systematic analysis of electronic and steric effects of substituents on the acidic strength of aliphatic and aromatic carboxylic acids with quantitative pK<sub>a</sub> data.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Quantitative pK<sub>a</sub> Scale:</b><br>&bull; Trifluoroacetic acid (CF<sub>3</sub>COOH): <b>pK<sub>a</sub> = 0.23</b>.<br>&bull; Trichloroacetic acid (CCl<sub>3</sub>COOH): <b>pK<sub>a</sub> = 0.65</b>.<br>&bull; Dichloroacetic acid (CHCl<sub>2</sub>COOH): <b>pK<sub>a</sub> = 1.29</b>.<br>&bull; Nitroacetic acid (NO<sub>2</sub>CH<sub>2</sub>COOH): <b>pK<sub>a</sub> = 1.68</b>.<br>&bull; Cyanoacetic acid (NCCH<sub>2</sub>COOH): <b>pK<sub>a</sub> = 2.47</b>.<br>&bull; Fluoroacetic acid (FCH<sub>2</sub>COOH): <b>pK<sub>a</sub> = 2.59</b>.<br>&bull; Chloroacetic acid (ClCH<sub>2</sub>COOH): <b>pK<sub>a</sub> = 2.87</b>.<br>&bull; Formic acid (HCOOH): <b>pK<sub>a</sub> = 3.75</b>.<br>&bull; Benzoic acid (C<sub>6</sub>H<sub>5</sub>COOH): <b>pK<sub>a</sub> = 4.20</b>.<br>&bull; Acetic acid (CH<sub>3</sub>COOH): <b>pK<sub>a</sub> = 4.76</b>.<br>&bull; Propanoic acid (CH<sub>3</sub>CH<sub>2</sub>COOH): <b>pK<sub>a</sub> = 4.88</b>.<br><br><b>2. Key Principles:</b><br>&bull; <b>-I / -M Groups (Electron-Withdrawing):</b> Disperse negative charge &rarr; stabilize RCOO<sup>-</sup> &rarr; increase acidity (lower pK<sub>a</sub>).<br>&bull; <b>+I Groups (Electron-Donating):</b> Intensify negative charge &rarr; destabilize RCOO<sup>-</sup> &rarr; decrease acidity (higher pK<sub>a</sub>).<br>&bull; <b>Position Effect:</b> -I effect decreases rapidly with distance: 2-chlorobutanoic (pK<sub>a</sub> 2.84) &gt; 3-chlorobutanoic (pK<sub>a</sub> 4.06) &gt; 4-chlorobutanoic (pK<sub>a</sub> 4.52).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q88: Describe the Hell-Volhard-Zelinsky (HVZ) reaction: complete mechanism, role of phosphorus, and synthetic transformations of &alpha;-halo acids.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Role of Red Phosphorus:</b> Red P reacts with halogen (X<sub>2</sub>) in situ to form phosphorus trihalide (PX<sub>3</sub>), which converts a small portion of carboxylic acid into acyl halide (R-CH<sub>2</sub>-CO-X). Acyl halide enolizes much more rapidly than free acid.<br><br><b>2. Step-by-Step Mechanism:</b><br>&bull; <b>Step 1:</b> R-CH<sub>2</sub>-COOH + PX<sub>3</sub> &rarr; R-CH<sub>2</sub>-CO-X + P(OH)<sub>3</sub>.<br>&bull; <b>Step 2 (Enolisation):</b> R-CH<sub>2</sub>-CO-X &#8652; R-CH=C(OH)-X (Enol form).<br>&bull; <b>Step 3 (Halogenation):</b> Enol attacks X<sub>2</sub> &rarr; R-CH(X)-CO-X + HX.<br>&bull; <b>Step 4 (Exchange):</b> R-CH(X)-CO-X + R-CH<sub>2</sub>-COOH &#8652; <b>R-CH(X)-COOH (&alpha;-Halocarboxylic acid)</b> + R-CH<sub>2</sub>-CO-X.<br><br><b>3. Synthetic Applications of &alpha;-Bromo Acids:</b><br>&bull; <b>Synthesis of &alpha;-Hydroxy Acids:</b> R-CH(Br)-COOH + aq. KOH &rarr; <b>R-CH(OH)-COOH</b> (e.g. Lactic acid).<br>&bull; <b>Synthesis of &alpha;-Amino Acids:</b> R-CH(Br)-COOH + excess NH<sub>3</sub> &rarr; <b>R-CH(NH<sub>2</sub>)-COOH</b> (e.g. Alanine).<br>&bull; <b>Synthesis of &alpha;,&beta;-Unsaturated Acids:</b> R-CH<sub>2</sub>-CH(Br)-COOH + alc. KOH &rarr; (&Delta;) &rarr; <b>R-CH=CH-COOH</b> (Cinnamic/Crotonic acid).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q89: Comprehensive Diagnostic Master Scheme: How to chemically distinguish between all functional pairs in aldehydes, ketones, and carboxylic acids.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Aldehyde vs Ketone:</b><br>&bull; <b>Tollens' Test:</b> Aldehydes form Silver Mirror; Ketones do not.<br>&bull; <b>Fehling's Test:</b> Aliphatic aldehydes form red Cu<sub>2</sub>O ppt; Ketones do not.<br><br><b>2. Aliphatic Aldehyde vs Aromatic Aldehyde:</b><br>&bull; <b>Fehling's Test:</b> Acetaldehyde reduces Fehling's solution (red ppt); Benzaldehyde does not.<br><br><b>3. Methyl Ketone vs Other Ketone:</b><br>&bull; <b>Iodoform Test:</b> Pentan-2-one (CH<sub>3</sub>COCH<sub>2</sub>CH<sub>2</sub>CH<sub>3</sub>) gives yellow CHI<sub>3</sub> crystals; Pentan-3-one does not.<br><br><b>4. Carboxylic Acid vs Phenol:</b><br>&bull; <b>NaHCO<sub>3</sub> Test:</b> Carboxylic acids produce brisk effervescence of CO<sub>2</sub>; Phenols do not.<br>&bull; <b>Neutral FeCl<sub>3</sub>:</b> Phenols give violet colour; Carboxylic acids (except formates/acetates) do not.<br><br><b>5. Formic Acid vs Acetic Acid:</b><br>&bull; <b>Tollens' / Fehling's Test:</b> Formic acid reduces both reagents; Acetic acid does not.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q90: Master Chemical Conversions Series 1: (i) Toluene to Benzaldehyde, (ii) Benzene to Benzaldehyde, (iii) Propanone to Propene, (iv) Ethanal to Lactic acid, (v) Propan-2-ol to Acetone.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>(i) Toluene &rarr; Benzaldehyde:</b> Etard reaction with CrO<sub>2</sub>Cl<sub>2</sub> in CS<sub>2</sub> followed by H<sub>3</sub>O<sup>+</sup>.<br><b>(ii) Benzene &rarr; Benzaldehyde:</b> Gattermann-Koch reaction with CO + HCl in presence of anhyd. AlCl<sub>3</sub>/CuCl.<br><b>(iii) Propanone &rarr; Propene:</b> 1. Reduce with NaBH<sub>4</sub> &rarr; Propan-2-ol. 2. Dehydrate with conc. H<sub>2</sub>SO<sub>4</sub> at 443 K &rarr; Propene.<br><b>(iv) Ethanal &rarr; Lactic acid:</b> 1. Add HCN &rarr; Acetaldehyde cyanohydrin [CH<sub>3</sub>CH(OH)CN]. 2. Acid hydrolysis with H<sub>3</sub>O<sup>+</sup> &rarr; Lactic acid [CH<sub>3</sub>CH(OH)COOH].<br><b>(v) Propan-2-ol &rarr; Acetone:</b> Catalytic dehydrogenation over heated Cu at 573 K (or oxidation with CrO<sub>3</sub>).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q91: Master Chemical Conversions Series 2: (i) Acetophenone to 2-Phenylbutan-2-ol, (ii) Benzaldehyde to Benzophenone, (iii) Acetic acid to Formic acid, (iv) Formic acid to Acetic acid, (v) Ethanoic acid to Propanoic acid.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>(i) Acetophenone &rarr; 2-Phenylbutan-2-ol:</b> React Acetophenone with Ethylmagnesium bromide (CH<sub>3</sub>CH<sub>2</sub>MgBr) followed by H<sub>3</sub>O<sup>+</sup>.<br><b>(ii) Benzaldehyde &rarr; Benzophenone:</b> 1. Oxidize with KMnO<sub>4</sub> &rarr; Benzoic acid. 2. Treat with SOCl<sub>2</sub> &rarr; Benzoyl chloride (C<sub>6</sub>H<sub>5</sub>COCl). 3. Friedel-Crafts with Benzene/AlCl<sub>3</sub> &rarr; Benzophenone.<br><b>(iii) Acetic acid &rarr; Formic acid (Chain Degradation):</b> 1. CH<sub>3</sub>COOH + NH<sub>3</sub> / &Delta; &rarr; CH<sub>3</sub>CONH<sub>2</sub>. 2. Hofmann bromamide (Br<sub>2</sub>/KOH) &rarr; CH<sub>3</sub>NH<sub>2</sub>. 3. HNO<sub>2</sub> &rarr; CH<sub>3</sub>OH. 4. Acidified KMnO<sub>4</sub> &rarr; HCOOH.<br><b>(iv) Formic acid &rarr; Acetic acid (Chain Ascent):</b> 1. Reduce with LiAlH<sub>4</sub> &rarr; CH<sub>3</sub>OH. 2. PCl<sub>5</sub> &rarr; CH<sub>3</sub>Cl. 3. KCN &rarr; CH<sub>3</sub>CN. 4. Acid hydrolysis H<sub>3</sub>O<sup>+</sup> &rarr; CH<sub>3</sub>COOH.<br><b>(v) Ethanoic acid &rarr; Propanoic acid:</b> 1. LiAlH<sub>4</sub> &rarr; Ethanol. 2. PBr<sub>3</sub> &rarr; Ethyl bromide. 3. KCN &rarr; Propionitrile. 4. H<sub>3</sub>O<sup>+</sup> &rarr; Propanoic acid.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q92: Multi-Step Roadmap 1: An organic compound A (C<sub>5</sub>H<sub>10</sub>O) forms a phenylhydrazone, gives a negative Tollens' test, and gives a positive Iodoform test. On reduction with Zn-Hg/HCl it gives 2-methylbutane. Identify A and write all reactions.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Deduction:</b><br>1. A (C<sub>5</sub>H<sub>10</sub>O) forms phenylhydrazone &rarr; Contains a carbonyl group (&gt;C=O).<br>2. Negative Tollens' test &rarr; It is a <b>Ketone</b>.<br>3. Positive Iodoform test &rarr; Contains a <b>methyl ketone (CH<sub>3</sub>-C=O)</b> group.<br>4. Clemmensen reduction yields 2-methylbutane [CH<sub>3</sub>-CH(CH<sub>3</sub>)-CH<sub>2</sub>CH<sub>3</sub>] &rarr; The skeleton is isopentane with carbonyl at C-2.<br><br><b>Identity:</b> <b>Compound A is 3-Methylbutan-2-one [(CH<sub>3</sub>)<sub>2</sub>CH-CO-CH<sub>3</sub>]</b>.<br><b>Reactions:</b><br>&bull; With Phenylhydrazine: (CH<sub>3</sub>)<sub>2</sub>CH-C(=N-NHPh)-CH<sub>3</sub>.<br>&bull; With I<sub>2</sub>/NaOH: (CH<sub>3</sub>)<sub>2</sub>CH-COONa + CHI<sub>3</sub>&darr; (Yellow ppt).<br>&bull; Clemmensen: (CH<sub>3</sub>)<sub>2</sub>CH-COCH<sub>3</sub> + Zn-Hg/HCl &rarr; (CH<sub>3</sub>)<sub>2</sub>CH-CH<sub>2</sub>CH<sub>3</sub>.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q93: Multi-Step Roadmap 2: An aromatic compound A (C<sub>8</sub>H<sub>8</sub>O) gives a positive 2,4-DNP test. On treatment with I<sub>2</sub>/NaOH, it gives a yellow precipitate of B and a compound C. Compound C on acidification yields D (C<sub>7</sub>H<sub>6</sub>O<sub>2</sub>). D on heating with soda-lime gives E (C<sub>6</sub>H<sub>6</sub>). Identify A, B, C, D, E.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Compound A:</b> <b>Acetophenone (C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub>)</b>.<br><b>Compound B:</b> <b>Iodoform (CHI<sub>3</sub>)</b> (yellow crystalline solid).<br><b>Compound C:</b> <b>Sodium benzoate (C<sub>6</sub>H<sub>5</sub>COONa)</b>.<br><b>Compound D:</b> <b>Benzoic acid (C<sub>6</sub>H<sub>5</sub>COOH)</b>.<br><b>Compound E:</b> <b>Benzene (C<sub>6</sub>H<sub>6</sub>)</b>.<br><b>Equations:</b> C<sub>6</sub>H<sub>5</sub>COCH<sub>3</sub> + 3 I<sub>2</sub> + 4 NaOH &rarr; CHI<sub>3</sub> + C<sub>6</sub>H<sub>5</sub>COONa &rarr; (H<sup>+</sup>) &rarr; C<sub>6</sub>H<sub>5</sub>COOH &rarr; (NaOH/CaO, &Delta;) &rarr; C<sub>6</sub>H<sub>6</sub> + Na<sub>2</sub>CO<sub>3</sub>.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q94: Multi-Step Roadmap 3: An organic compound A (C<sub>3</sub>H<sub>6</sub>O) on treatment with HCN forms B. B on acidic hydrolysis yields an optically active compound C (C<sub>4</sub>H<sub>8</sub>O<sub>3</sub>). C on heating with conc. H<sub>2</sub>SO<sub>4</sub> gives D (C<sub>4</sub>H<sub>6</sub>O<sub>2</sub>). Identify A, B, C, D.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Compound A:</b> <b>Propanal (CH<sub>3</sub>CH<sub>2</sub>CHO)</b>.<br><b>Compound B:</b> <b>2-Hydroxybutanenitrile [CH<sub>3</sub>CH<sub>2</sub>CH(OH)CN]</b>.<br><b>Compound C:</b> <b>2-Hydroxybutanoic acid [CH<sub>3</sub>CH<sub>2</sub>CH(OH)COOH]</b> (Contains an asymmetric chiral carbon C-2 &bull; optically active).<br><b>Compound D:</b> <b>But-2-enoic acid (Crotonic acid, CH<sub>3</sub>CH=CHCOOH)</b> (Elimination of water from C).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q95: Multi-Step Roadmap 4: Primary alkyl halide A (C<sub>4</sub>H<sub>9</sub>Br) reacted with alcoholic KOH to give compound B. B reacted with HBr to give C which was an isomer of A. A on reaction with Na/ether gave D (C<sub>8</sub>H<sub>18</sub>). B on ozonolysis followed by Zn/H<sub>2</sub>O gave two molecules of ethanal. Identify A to D.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\">Since ozonolysis of B yields two molecules of ethanal (2 CH<sub>3</sub>CHO), <b>Compound B must be But-2-ene (CH<sub>3</sub>CH=CHCH<sub>3</sub>)</b>.<br><b>Compound A:</b> <b>1-Bromobutane (CH<sub>3</sub>CH<sub>2</sub>CH<sub>2</sub>CH<sub>2</sub>Br)</b> (Primary alkyl halide).<br><b>Compound C:</b> <b>2-Bromobutane (CH<sub>3</sub>CH(Br)CH<sub>2</sub>CH<sub>3</sub>)</b> (Markovnikov addition of HBr to B).<br><b>Compound D:</b> <b>n-Octane (CH<sub>3</sub>(CH<sub>2</sub>)<sub>6</sub>CH<sub>3</sub>)</b> (Wurtz coupling of A: 2 C<sub>4</sub>H<sub>9</sub>Br + 2 Na &rarr; C<sub>8</sub>H<sub>18</sub> + 2 NaBr).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q96: Explain the mechanism of Electrophilic Substitution in Benzoic Acid (Nitration and Bromination) and why Friedel-Crafts fails.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Directing Influence of -COOH:</b> The carboxyl carbon is bonded to oxygen via a double bond. Oxygen pulls &pi;-electrons, making carbonyl carbon positive, which pulls &pi;-electrons from the benzene ring by resonance (-M effect). Canonical structures show formal positive charges at ortho and para positions. Electrophiles attack the comparatively less deactivated <b>meta position</b>.<br><br><b>1. Nitration:</b> Benzoic acid + conc. HNO<sub>3</sub> + conc. H<sub>2</sub>SO<sub>4</sub> &rarr; (373 K) &rarr; <b>3-Nitrobenzoic acid (m-nitrobenzoic acid)</b>.<br><b>2. Bromination:</b> Benzoic acid + Br<sub>2</sub> / FeBr<sub>3</sub> &rarr; <b>3-Bromobenzoic acid (m-bromobenzoic acid)</b>.<br><b>3. Failure of Friedel-Crafts Reaction:</b> (1) The -COOH group is strongly deactivating; (2) The Lewis acid catalyst (anhyd. AlCl<sub>3</sub>) forms a coordinate bond with the oxygen lone pairs of -COOH, completely deactivating the catalyst and benzene ring.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q97: Describe the synthesis of Carboxylic Acids using Grignard Reagents (Carbonation) with mechanism and limitations.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>Principle:</b> Grignard reagent (RMgX) adds nucleophilically across the C=O bond of dry carbon dioxide (dry ice) in anhydrous ether:<br><br><b>Mechanism:</b><br>&bull; <b>Step 1 (Nucleophilic Addition):</b> The nucleophilic carbanion (R<sup>&delta;-</sup>) attacks the electrophilic carbon of CO<sub>2</sub> (O=C=O) to form a halomagnesium carboxylate salt: R-MgX + O=C=O &rarr; (Dry ether) &rarr; <b>R-COOMgX</b>.<br>&bull; <b>Step 2 (Acidic Hydrolysis):</b> Hydrolysis with dilute mineral acid liberates the free carboxylic acid: R-COOMgX + H<sub>3</sub>O<sup>+</sup> &rarr; <b>R-COOH + Mg(OH)X</b>.<br><br><b>Synthetic Importance:</b> Excellent method to ascend the homologous series by exactly one carbon atom (e.g. CH<sub>3</sub>MgBr + CO<sub>2</sub> &rarr; CH<sub>3</sub>COOH; C<sub>6</sub>H<sub>5</sub>MgBr + CO<sub>2</sub> &rarr; C<sub>6</sub>H<sub>5</sub>COOH).</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q98: Master Reaction Mechanisms: (i) Addition of Alcohols to Aldehydes (Acetal formation), (ii) Addition of 2,4-DNP to Ketones.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>(i) Acetal Formation Mechanism:</b><br>1. Carbonyl oxygen of aldehyde is protonated by dry HCl gas: RCHO + H<sup>+</sup> &#8652; RCH=O<sup>+</sup>H.<br>2. First alcohol molecule (R'OH) attacks &rarr; forms <b>Hemiacetal [R-CH(OH)(OR')]</b>.<br>3. Protonation of -OH group converts it into -O<sup>+</sup>H<sub>2</sub>, which departs as H<sub>2</sub>O, forming a resonance-stabilized carbocation [R-CH=O<sup>+</sup>R'].<br>4. Second alcohol molecule attacks &rarr; deprotonation yields <b>Acetal [R-CH(OR')<sub>2</sub>]</b>.<br><br><b>(ii) 2,4-DNP Addition-Elimination Mechanism:</b><br>1. Nucleophilic attack of hydrazine -NH<sub>2</sub> on protonated carbonyl carbon.<br>2. Proton transfer forms tetrahedral carbinolamine intermediate [&gt;C(OH)-NH-NH-Ar].<br>3. Elimination of a water molecule yields the stable conjugated <b>2,4-Dinitrophenylhydrazone (&gt;C=N-NH-C<sub>6</sub>H<sub>3</sub>(NO<sub>2</sub>)<sub>2</sub>)</b> yellow/orange precipitate.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q99: Qualitative and Quantitative comparison between Aliphatic and Aromatic Aldehydes and Ketones across physical properties, chemical reactivity, and spectral trends.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Reactivity towards Nucleophiles:</b> Aliphatic aldehydes &gt; Aromatic aldehydes &gt; Aliphatic ketones &gt; Aromatic ketones.<br><i>Reason:</i> Resonance in aromatic systems (+R) delocalizes ring electrons into carbonyl, reducing carbon electrophilicity; steric crowding by phenyl ring also hinders approach.<br><br><b>2. Oxidation Susceptibility:</b> Aliphatic aldehydes reduce both Tollens' and Fehling's reagents; Aromatic aldehydes reduce Tollens' but NOT Fehling's; Ketones resist both.<br><br><b>3. &alpha;-Hydrogen Reactions:</b> Aliphatic aldehydes with &alpha;-H undergo Aldol condensation; Aromatic aldehydes (no &alpha;-H) undergo Cannizzaro reaction or Cross-Aldol with aliphatic ketones.<br><br><b>4. Dipole Moments &amp; Boiling Points:</b> Aromatic ketones (Acetophenone 2.9 D) have higher dipole moments and boiling points (202 &deg;C) than aliphatic ketones (Acetone 56 &deg;C) due to extended conjugation.</div>\n  </div>\n\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 214, 0, 0.25); border-radius: 8px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FFD600; margin: 0 0 10px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">\n      Q100: Comprehensive Synthetic Roadmaps &amp; Interconversions: Overview of Carbonyl &amp; Carboxyl Interconversions in Organic Chemistry.\n    </h3>\n    <div style=\"color: #FFFFFF; line-height: 1.75; font-size: 15.5px;\"><b>1. Interconversion Map:</b><br>&bull; <b>Alcohol &harr; Carbonyl:</b> 1&deg; Alcohol &rarr; (PCC) &rarr; Aldehyde &rarr; (NaBH<sub>4</sub>) &rarr; 1&deg; Alcohol.<br>&bull; <b>Carbonyl &rarr; Acid:</b> Aldehyde &rarr; (Tollens' / KMnO<sub>4</sub>) &rarr; Carboxylic acid.<br>&bull; <b>Acid &rarr; Alcohol:</b> RCOOH &rarr; (LiAlH<sub>4</sub>) &rarr; RCH<sub>2</sub>OH.<br>&bull; <b>Acid &rarr; Acyl Chloride &rarr; Aldehyde:</b> RCOOH &rarr; (SOCl<sub>2</sub>) &rarr; RCOCl &rarr; (Pd-BaSO<sub>4</sub>, H<sub>2</sub>) &rarr; RCHO (Rosenmund).<br>&bull; <b>Carbonyl &rarr; Alkane:</b> &gt;C=O &rarr; (Clemmensen Zn-Hg/HCl or Wolff-Kishner NH<sub>2</sub>NH<sub>2</sub>/KOH) &rarr; &gt;CH<sub>2</sub>.<br>&bull; <b>Acid &rarr; &alpha;-Halo Acid &rarr; &alpha;-Amino Acid:</b> RCH<sub>2</sub>COOH &rarr; (Br<sub>2</sub>/Red P) &rarr; RCH(Br)COOH &rarr; (NH<sub>3</sub>) &rarr; RCH(NH<sub>2</sub>)COOH.<br>&bull; <b>Decarboxylation:</b> RCOONa + NaOH/CaO &rarr; R-H + Na<sub>2</sub>CO<sub>3</sub>.</div>\n  </div>\n</div>\n";

